          {/* Ações rápidas */}
          <div className="flex items-center gap-1">
            {insight.tipo === 'encalhe' && (
              <Button variant="ghost" size="sm" className="text-[10px] !px-2 !py-1">
                Criar promoção
              </Button>
            )}
            {insight.tipo === 'oportunidade_b' && (
              <Button variant="ghost" size="sm" className="text-[10px] !px-2 !py-1">
                Destacar produto
              </Button>
            )}
          </div>
        </div>
      </div>

      {/* Modal de produtos */}
      {insight.produtos && (
        <ProductListModal
          open={showProdutos}
          onClose={() => setShowProdutos(false)}
          tipo={insight.tipo}
          produtos={insight.produtos}
        />
      )}
    </div>
  )
}

/** Card individual de indicador macroeconômico com estado disponível/indisponível. */
import { TrendingUp, TrendingDown, Minus, AlertCircle, HelpCircle } from 'lucide-react'
import type { MacroIndicator } from '../../types/macro'

interface Props {
  indicador: MacroIndicator
}

function formatarData(iso: string): string {
  try {
    const d = new Date(iso)
    return d.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' })
  } catch {
    return iso
  }
}

export default function MacroCard({ indicador }: Props) {
  if (!indicador.disponivel) {
    return (
      <div className="shrink-0 w-[170px] bg-danger/[0.06] rounded-xl border border-danger/20 p-3 text-center snap-start">
        {/* Rótulo */}
        <span className="text-[10px] font-semibold text-text-muted uppercase tracking-wider block mb-1">
          {indicador.rotulo}
        </span>

        {/* Estado indisponível */}
        <div className="flex items-center justify-center gap-1.5 mb-2" title={indicador.mensagem || undefined}>
          <AlertCircle size={14} className="text-danger shrink-0" />
          <span className="text-xs font-medium text-danger">API indisponível</span>
        </div>

        {/* Timestamp */}
        <span className="text-[9px] text-text-muted block leading-tight">
          Falha em: {formatarData(indicador.consultado_em)}
        </span>
      </div>
    )
  }

  // Determinar direção da tendência baseado no valor vs. referência
  // Indicadores > 5% são "altos" (exceto desemprego que > 12% é alto)
  const isElevado = indicador.valor !== null && (
    indicador.chave.startsWith('selic') ? indicador.valor > 10 :
    indicador.chave === 'desemprego' ? indicador.valor > 12 :
    indicador.valor > 5
  )

  const TrendIcon = isElevado ? TrendingUp : (indicador.valor !== null && indicador.valor < 2 ? TrendingDown : Minus)
  const trendColor = isElevado ? 'text-danger' : (indicador.valor !== null && indicador.valor < 2 ? 'text-success' : 'text-text-muted')

  return (
    <div className="shrink-0 w-[170px] bg-bg-card rounded-xl border border-border/40 p-3 hover:border-border/70 transition-colors text-center snap-start">
      {/* Rótulo */}
      <span className="text-[10px] font-semibold text-text-muted uppercase tracking-wider block mb-1">
        {indicador.rotulo}
      </span>

      {/* Valor + tendência */}
      <div className="flex items-center justify-center gap-1.5 mb-0.5">
        <span className="text-lg font-bold text-text-primary font-display tracking-tight">
          {indicador.valor?.toFixed(2).replace('.', ',')}
          <span className="text-xs font-medium text-text-muted ml-0.5">{indicador.unidade}</span>
        </span>
        <TrendIcon size={14} className={trendColor} />
      </div>

      {/* Período de referência */}
      {indicador.periodo_ref && (
        <span className="text-[10px] text-text-muted block">
          {indicador.periodo_ref}
        </span>
      )}

      {/* Timestamp de consulta */}
      <div className="flex items-center justify-center gap-1 mt-1.5 pt-1.5 border-t border-border/20">
        <HelpCircle size={8} className="text-text-muted" />
        <span className="text-[8px] text-text-muted">
          {formatarData(indicador.consultado_em)}
        </span>
      </div>
    </div>
  )
}

/** Strip horizontal de indicadores macroeconômicos. */
import { AlertCircle, BarChart3 } from 'lucide-react'
import Skeleton from '../ui/Skeleton'
import MacroCard from './MacroCard'
import type { MacroIndicator } from '../../types/macro'

interface Props {
  indicadores: MacroIndicator[]
  loading: boolean
  erro: string | null
}

export default function MacroStrip({ indicadores, loading, erro }: Props) {
  // Loading: skeleton shimmer
  if (loading) {
    return (
      <div className="flex gap-3 overflow-x-auto pb-2">
        {Array.from({ length: 5 }).map((_, i) => (
          <Skeleton key={i} className="h-[98px] w-[170px] shrink-0 rounded-xl" />
        ))}
      </div>
    )
  }

  // Erro: banner silencioso (não crítico — indicadores são complementares)
  if (erro) {
    return (
      <div className="flex items-center gap-2 px-3 py-2 rounded-lg bg-warning/[0.06] border border-warning/20 text-[11px] text-warning">
        <AlertCircle size={12} />
        <span>Indicadores macroeconômicos temporariamente indisponíveis</span>
      </div>
    )
  }

  // Empty: esconder (sem indicadores configurados)
  if (indicadores.length === 0) {
    return null
  }

  return (
    <div>
      {/* Header */}
      <div className="flex items-center gap-2 mb-2.5">
        <BarChart3 size={14} className="text-text-muted" />
        <span className="text-[10px] font-semibold text-text-muted uppercase tracking-wider">
          Contexto Macroeconômico
        </span>
        <span className="text-[9px] text-text-muted bg-bg-hover/50 px-1.5 py-0.5 rounded-full">
          {indicadores.filter(i => i.disponivel).length}/{indicadores.length} disponíveis
        </span>
      </div>

      {/* Strip com scroll horizontal */}
      <div className="flex gap-3 overflow-x-auto pb-2 scrollbar-thin snap-x snap-mandatory -mx-1 px-1 scroll-smooth">
        {indicadores.map(ind => (
          <MacroCard key={ind.chave} indicador={ind} />
        ))}
      </div>
    </div>
  )
}

/** Modal com tabela de produtos de um insight + export CSV. */
import { useMemo } from 'react'
import { FileDown } from 'lucide-react'
import Modal from '../ui/Modal'
import Button from '../ui/Button'
import type { ProdutoInsight, InsightTipo } from '../../types/intelligence'
import { formatCurrency } from '../../utils/formatters'

interface Props {
  open: boolean
  onClose: () => void
  tipo: InsightTipo
  produtos: ProdutoInsight[]
}

type Coluna = { key: string; label: string; render: (p: ProdutoInsight) => string }

function getColunas(tipo: InsightTipo): Coluna[] {
  const base: Coluna[] = [
    { key: 'codigo', label: 'Código', render: p => p.codigo },
    { key: 'nome', label: 'Nome', render: p => p.nome },
  ]

  const extras: Record<InsightTipo, Coluna[]> = {
    encalhe: [
      { key: 'estoque', label: 'Estoque', render: p => String(p.estoque ?? '—') },
      { key: 'dias_parado', label: 'Dias parado', render: p => String(p.dias_parado ?? '—') },
      { key: 'valor_estimado', label: 'Valor estimado', render: p => p.valor_estimado != null ? formatCurrency(p.valor_estimado) : '—' },
    ],
    taxa_troca: [
      { key: 'taxa_troca', label: 'Taxa (%)', render: p => p.taxa_troca != null ? `${(p.taxa_troca * 100).toFixed(1)}%` : '—' },
      { key: 'qtd_trocas', label: 'Trocas', render: p => String(p.qtd_trocas ?? '—') },
      { key: 'qtd_vendas', label: 'Vendas', render: p => String(p.qtd_vendas ?? '—') },
    ],
    sazonalidade: [
      { key: 'crescimento_qtd', label: 'Crescimento (%)', render: p => p.crescimento_qtd != null ? `${(p.crescimento_qtd * 100).toFixed(0)}%` : '—' },
      { key: 'qtd_anterior', label: 'Qtd anterior', render: p => String(p.qtd_anterior ?? '—') },
      { key: 'qtd_atual', label: 'Qtd atual', render: p => String(p.qtd_atual ?? '—') },
      { key: 'valor_atual', label: 'Valor atual', render: p => p.valor_atual != null ? formatCurrency(p.valor_atual) : '—' },
    ],
    margem_erosao: [
      { key: 'margem_anterior', label: 'Margem ant. (%)', render: p => p.margem_anterior != null ? `${p.margem_anterior}%` : '—' },
      { key: 'margem_atual', label: 'Margem atual (%)', render: p => p.margem_atual != null ? `${p.margem_atual}%` : '—' },
      { key: 'variacao_pp', label: 'Variação (pp)', render: p => p.variacao_pp != null ? `${p.variacao_pp.toFixed(1)}` : '—' },
    ],
    oportunidade_b: [
      { key: 'margem_b', label: 'Margem B (%)', render: p => p.margem_b != null ? `${p.margem_b}%` : '—' },
      { key: 'margem_lider', label: 'Média A (%)', render: p => p.margem_lider != null ? `${p.margem_lider}%` : '—' },
      { key: 'upside_margem', label: 'Upside (%)', render: p => p.upside_margem != null ? `${p.upside_margem}%` : '—' },
      { key: 'potencial_ganho_mensal', label: 'Potencial/mês', render: p => p.potencial_ganho_mensal != null ? formatCurrency(p.potencial_ganho_mensal) : '—' },
    ],
    macro_contexto: [],
    outro: [],
  }

  return [...base, ...extras[tipo]]
}

function exportCSV(produtos: ProdutoInsight[], colunas: Coluna[], tipo: string) {
  const header = colunas.map(c => c.label).join(',')
  const rows = produtos.map(p =>
    colunas.map(c => `"${c.render(p).replace(/"/g, '""')}"`).join(',')
  )
  const csv = `\uFEFF${header}\n${rows.join('\n')}`
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = `insight_${tipo}_${Date.now()}.csv`
  a.click()
  URL.revokeObjectURL(url)
}

export default function ProductListModal({ open, onClose, tipo, produtos }: Props) {
  const colunas = useMemo(() => getColunas(tipo), [tipo])
  const tipoLabel = tipo.replace(/_/g, ' ')

  return (
    <Modal
      open={open}
      onClose={onClose}
      title={`${produtos.length} ${tipoLabel}`}
      size="xl"
      actions={
        <Button variant="secondary" size="sm" onClick={() => exportCSV(produtos, colunas, tipo)}>
          <FileDown size={14} className="mr-1" />
          Exportar CSV
        </Button>
      }
    >
      <div className="overflow-x-auto">
        <table className="w-full text-sm text-left">
          <thead>
            <tr className="border-b border-border text-text-muted text-[11px] uppercase tracking-wider">
              {colunas.map(col => (
                <th key={col.key} className="py-2 pr-4 font-medium">{col.label}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {produtos.map((p, i) => (
              <tr key={p.codigo} className={i < produtos.length - 1 ? 'border-b border-border/50' : ''}>
                {colunas.map(col => (
                  <td key={col.key} className="py-2 pr-4 text-text-primary whitespace-nowrap">
                    {col.render(p)}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
        {produtos.length === 0 && (
          <p className="text-sm text-text-muted py-4 text-center">Nenhum produto listado.</p>
        )}
      </div>
    </Modal>
  )
}

/** Card de resumo executivo premium — hero principal da página Intelligence. */
import { Sparkles, Cpu, TrendingUp, TrendingDown, Minus, ChevronRight } from 'lucide-react'
import type { Fonte } from '../../types/intelligence'
import { formatDateWithWeekday } from '../../utils/formatters'

interface Props {
  texto: string
  fonte: Fonte
  geradoEm: string
}

const FONTE_META: Record<Fonte, { label: string; icon: React.ReactNode; color: string }> = {
  claude: { label: 'Claude Sonnet', icon: <Sparkles size={12} />, color: 'text-purple-400' },
  gpt4o_mini: { label: 'GPT-4o Mini', icon: <Sparkles size={12} />, color: 'text-emerald-400' },
  deterministico: { label: 'Síntese simplificada', icon: <Cpu size={12} />, color: 'text-blue-400' },
}

/** Extrai um valor monetário do texto do resumo (ex: "R$ 780.532,89") */
function extractRevenue(text: string): string | null {
  const match = text.match(/[R]\$[\s]*[\d.,]+/)
  return match?.[0] ?? null
}

/** Extrai número de oportunidades (ex: "5 oportunidades") */
function extractOpportunities(text: string): string | null {
  const match = text.match(/(\d+)\s*oportunidades?/)
  return match?.[1] ?? null
}

/** Determina tendência baseada em palavras-chave */
function detectTrend(text: string): 'up' | 'down' | 'stable' {
  const lower = text.toLowerCase()
  if (lower.includes('crescimento') || lower.includes('aumento') || lower.includes('melhora'))
    return 'up'
  if (lower.includes('queda') || lower.includes('redução') || lower.includes('atenção'))
    return 'down'
  return 'stable'
}

const TREND_CONFIG = {
  up: { icon: TrendingUp, label: 'Tendência positiva', color: 'text-success' },
  down: { icon: TrendingDown, label: 'Atenção necessária', color: 'text-danger' },
  stable: { icon: Minus, label: 'Estável', color: 'text-text-muted' },
}

