                <h2 className="text-lg font-bold text-text-primary font-display tracking-tight">
                  Resumo Executivo
                </h2>
                <p className="text-[11px] text-text-muted">
                  Análise estratégica · {formatDateWithWeekday(geradoEm.split('T')[0])}
