import { useLocation, useNavigate } from 'react-router-dom'
import { useAuth } from '../../hooks/useAuth'
import { ClipboardList, LayoutDashboard, Search, Package, Settings, ShieldAlert, Tags, Sparkles } from 'lucide-react'
