interface Props {
  collapsed: boolean
  onToggle: () => void
}

export default function Sidebar({ collapsed, onToggle }: Props) {
  const location = useLocation()
  const navigate = useNavigate()
  const { getRole, logout, getNomeExibicao } = useAuth()
  const role = getRole()
  const displayName = getNomeExibicao()

  const isActive = (path: string) => {
    if (path === '/bi') return location.pathname === '/bi' || (location.pathname.startsWith('/bi/') && !location.pathname.startsWith('/bi/intelligence'))
    if (path === '/bi/intelligence') return location.pathname.startsWith('/bi/intelligence')
    if (path === '/admin') return location.pathname === '/admin' || (location.pathname.startsWith('/admin/') && !location.pathname.startsWith('/admin/usuarios') && !location.pathname.startsWith('/admin/configuracoes') && !location.pathname.startsWith('/admin/etiquetas'))
    if (path === '/admin/usuarios') return location.pathname.startsWith('/admin/usuario')
    if (path === '/admin/configuracoes') return location.pathname.startsWith('/admin/configuracoes')
    if (path === '/etiquetas') return location.pathname.startsWith('/etiquetas')
    return location.pathname === path
  }

  const handleLogout = async () => {
    await logout()
    navigate('/login')
  }

  function navBtnClass(active: boolean, collapsed: boolean): string {
    const base = 'relative w-full flex items-center gap-3 rounded-lg text-sm font-medium transition-all duration-150 text-left'
    if (collapsed) {
      return `${base} justify-center px-0 py-2.5 ${
        active
          ? 'text-primary bg-primary/[0.1] shadow-[inset_0_0_0_1px_color-mix(in_srgb,var(--color-primary),12%)]'
          : 'text-text-muted hover:text-text-secondary hover:bg-bg-hover'
      }`
    }
    return `${base} px-3 py-2.5 ${
      active
        ? 'text-primary bg-primary/[0.08] shadow-[inset_0_0_0_1px_color-mix(in_srgb,var(--color-primary),10%)] font-semibold'
        : 'text-text-muted hover:text-text-secondary hover:bg-bg-hover'
    }`
  }

  function bottomBtnClass(collapsed: boolean, danger = false): string {
    const base = 'w-full flex items-center gap-3 rounded-lg text-sm transition-all duration-150'
    const color = danger
      ? 'text-danger hover:bg-danger/[0.08]'
      : 'text-text-muted hover:text-text-secondary hover:bg-bg-hover'
    if (collapsed) return `${base} justify-center px-0 py-2.5 ${color}`
    return `${base} px-3 py-2 ${color}`
  }

  return (
    <aside
      className={`fixed left-0 top-0 h-full z-40 bg-bg-sidebar border-r border-border/60 flex flex-col transition-all duration-300 ease-out ${
        collapsed ? 'w-[64px]' : 'w-[var(--sidebar-width)]'
      }`}
    >
      {/* Logo + toggle */}
      <div className={`flex items-center h-[var(--header-height)] border-b border-border/50 shrink-0 ${
        collapsed ? 'justify-center px-0' : 'justify-between px-5'
      }`}>
        {!collapsed && <Logo height={28} className="text-primary shrink-0" />}
        <button
          onClick={onToggle}
          className="p-1.5 rounded-lg text-text-muted hover:text-text-primary hover:bg-bg-hover transition"
          aria-label={collapsed ? 'Expandir sidebar' : 'Recolher sidebar'}
          title={collapsed ? 'Expandir' : 'Recolher'}
        >
          {collapsed ? <PanelRightClose size={16} /> : <ChevronLeft size={16} />}
        </button>
      </div>

      {/* Navigation */}
      <nav className="flex-1 overflow-y-auto py-5 space-y-6">
        {navGroups.map((group) => {
          const visibleItems = group.items.filter(item => role && item.roles.includes(role))
          if (visibleItems.length === 0) return null

          return (
            <div key={group.label}>
              {/* Group label */}
              {!collapsed && (
                <div className="px-5 mb-2">
                  <span className="text-[10px] font-semibold text-text-muted uppercase tracking-[0.12em] select-none">
                    {group.label}
                  </span>
                </div>
              )}

              {/* Items */}
              <div className="space-y-0.5 px-2">
                {visibleItems.map((item) => {
                  const active = isActive(item.path)
                  return (
                    <button
                      key={item.path}
                      onClick={() => navigate(item.path)}
                      className={navBtnClass(active, collapsed)}
                      title={collapsed ? item.label : undefined}
                    >
                      <span className="shrink-0">{item.icon}</span>
                      {!collapsed && <span className="truncate">{item.label}</span>}
                    </button>
                  )
                })}
              </div>
            </div>
          )
        })}
      </nav>

      {/* Bottom — User area */}
      <div className={`border-t border-border/50 py-3 space-y-1 ${collapsed ? 'px-1' : 'px-3'}`}>
        {/* User profile */}
        {!collapsed ? (
          <div className="flex items-center gap-3 px-2 py-2 rounded-lg">
            <UserAvatar name={displayName} size="sm" />
            <div className="flex-1 min-w-0">
              <p className="text-sm font-medium text-text-primary truncate">{displayName}</p>
              <div className="flex items-center gap-1.5 mt-0.5">
                <span className="w-1.5 h-1.5 rounded-full bg-success" />
                <span className="text-[10px] text-text-muted">Online</span>
              </div>
            </div>
          </div>
        ) : (
          <div className="flex justify-center py-2">
            <UserAvatar name={displayName} size="sm" />
          </div>
        )}

        {/* Support */}
        <button className={bottomBtnClass(collapsed)} title={collapsed ? 'Ajuda' : undefined}>
          <HelpCircle size={16} className="shrink-0" />
          {!collapsed && <span>Ajuda</span>}
        </button>

        {/* Logout */}
        <button
          onClick={handleLogout}
          className={bottomBtnClass(collapsed, true)}
          title={collapsed ? 'Sair' : undefined}
        >
          <LogOut size={16} className="shrink-0" />
          {!collapsed && <span>Sair</span>}
        </button>
      </div>
    </aside>
  )
}

import { useEffect, useRef, useState, useCallback } from 'react'
import { BrowserMultiFormatReader } from '@zxing/browser'
import { X, ScanLine, CameraOff, Sun } from 'lucide-react'
import Button from './ui/Button'

interface Props {
  onLeitura: (codigo: string) => void
  onFechar: () => void
}

export default function LeitorCodigo({ onLeitura, onFechar }: Props) {
  const videoRef = useRef<HTMLVideoElement>(null)
  const [erro, setErro] = useState('')
  const [flash, setFlash] = useState(false)
  const readerRef = useRef<BrowserMultiFormatReader | null>(null)
  const controlsRef = useRef<{ stop: () => void } | null>(null)
  const hasReadRef = useRef(false)
  const stoppedRef = useRef(false)

  const onLeituraRef = useRef(onLeitura)
  useEffect(() => { onLeituraRef.current = onLeitura }, [onLeitura])

  const cleanup = useCallback(() => {
    stoppedRef.current = true
    try { controlsRef.current?.stop() } catch { /* already stopped */ }
    controlsRef.current = null
    readerRef.current = null
    BrowserMultiFormatReader.releaseAllStreams()
  }, [])

  function toggleFlash() {
    const video = videoRef.current
    if (!video) return
    const stream = video.srcObject as MediaStream | null
    const track = stream?.getVideoTracks()[0]
    if (!track) return
    const nova = !flash
    setFlash(nova)
    track.applyConstraints({ advanced: [{ torch: nova }] as Record<string, unknown>[] }).catch(() => {
      setFlash(false) // torch não suportado nesse dispositivo
    })
  }

  useEffect(() => {
    hasReadRef.current = false
    stoppedRef.current = false  // limpa trava do Strict Mode (desmonta + remonta)
    const reader = new BrowserMultiFormatReader()
    readerRef.current = reader

    reader.decodeFromVideoDevice(undefined, videoRef.current!, (result) => {
      if (stoppedRef.current) return
      if (result && !hasReadRef.current) {
        hasReadRef.current = true
        navigator.vibrate?.(20)
        onLeituraRef.current(result.getText())
        cleanup()
        // Defer close to next tick so state updates propagate first
        setTimeout(() => onFechar(), 50)
      }
    })
      .then(controls => { controlsRef.current = controls })
      .catch(() => setErro('Não foi possível acessar a câmera. Verifique as permissões.'))

    return cleanup
  }, [cleanup, onFechar])

  return (
    <div className="fixed inset-0 bg-black/90 z-50 flex flex-col items-center justify-center px-4">
      <div className="relative w-full max-w-sm bg-slate-950 rounded-2xl overflow-hidden">
        <video ref={videoRef} className="w-full aspect-[4/3] object-cover" autoPlay muted playsInline />

        {/* Scan frame overlay */}
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
          <div className="relative">
            <ScanLine size={40} className="text-white/30" />
          </div>
        </div>

        {/* Flash toggle */}
        <button
          onClick={toggleFlash}
          className={`absolute top-3 right-3 z-10 p-2.5 rounded-xl transition ${
            flash
              ? 'bg-yellow-400 text-yellow-900 shadow-lg shadow-yellow-400/40'
              : 'bg-white/20 text-white/70 hover:bg-white/30'
          }`}
          aria-label={flash ? 'Desligar flash' : 'Ligar flash'}
          title={flash ? 'Desligar flash' : 'Ligar flash'}
        >
          <Sun size={18} />
        </button>

        {erro && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/80 gap-3">
            <CameraOff size={32} className="text-red-400" />
            <p className="text-red-400 text-sm text-center px-6">{erro}</p>
            <Button variant="secondary" size="sm" onClick={() => onFechar()}>Fechar</Button>
          </div>
        )}
      </div>

      <div className="w-full max-w-sm mt-4 flex items-center justify-between">
        <p className="text-slate-500 text-xs">
          Aponte para o código de barras
        </p>
        <button
          onClick={() => { cleanup(); onFechar() }}
          className="text-slate-400 hover:text-white transition flex items-center gap-1 text-sm"
        >
          <X size={16} /> Fechar
        </button>
      </div>
    </div>
  )
}

import { useState, useEffect, useRef } from 'react'
import { listarContatosEmail, criarContatoEmail, atualizarContatoEmail, removerContatoEmail } from '../api/email'
import type { EmailContato } from '../api/email'
import { useToast } from '../hooks/useToast'
import { Plus, X, Loader2 } from 'lucide-react'

export default function ListaContatosEmail() {
  const { toast } = useToast()
  const [contatos, setContatos] = useState<EmailContato[]>([])
  const [loading, setLoading] = useState(true)
  const [savingIds, setSavingIds] = useState<Set<number>>(new Set())
  const contatosRef = useRef(contatos)

  useEffect(() => {
    contatosRef.current = contatos
  }, [contatos])
  const debounceTimers = useRef<Record<string, ReturnType<typeof setTimeout>>>({})

  useEffect(() => {
    listarContatosEmail()
      .then(setContatos)
      .catch(() => toast({ type: 'error', message: 'Erro ao carregar contatos de email' }))
      .finally(() => setLoading(false))
  }, []) // eslint-disable-line react-hooks/exhaustive-deps -- Mount-only fetch

  useEffect(() => {
    const timers = debounceTimers.current
    return () => { Object.values(timers).forEach(clearTimeout) }
  }, [])

  async function handleAdicionar() {
    try {
      const novo = await criarContatoEmail({ email: '', nome: '' })
      setContatos((prev) => [...prev, novo])
    } catch {
      toast({ type: 'error', message: 'Erro ao adicionar contato' })
    }
  }

  async function handleRemover(id: number) {
    try {
      await removerContatoEmail(id)
      setContatos((prev) => prev.filter((c) => c.id !== id))
    } catch {
      toast({ type: 'error', message: 'Erro ao remover contato' })
    }
  }

  function handleUpdate(id: number, field: 'nome' | 'email', value: string) {
    setContatos((prev) =>
      prev.map((c) => (c.id === id ? { ...c, [field]: value } : c))
    )
    setSavingIds((prev) => new Set(prev).add(id))
    const key = `${id}-${field}`
    clearTimeout(debounceTimers.current[key])
    debounceTimers.current[key] = setTimeout(async () => {
      delete debounceTimers.current[key]
      const contato = contatosRef.current.find((c) => c.id === id)
      if (!contato) return
      try {
        const result = await atualizarContatoEmail(id, { nome: contato.nome, email: contato.email })
        setContatos((prev) => prev.map((c) => (c.id === id ? result : c)))
      } catch {
        toast({ type: 'error', message: 'Erro ao salvar contato' })
      } finally {
        setSavingIds((prev) => {
          const next = new Set(prev)
          next.delete(id)
          return next
        })
      }
    }, 600)
  }

  if (loading) {
    return <p className="text-xs text-text-muted">Carregando contatos...</p>
  }

  return (
    <div className="flex flex-col gap-2">
      {/* Column headers */}
      <div className="hidden sm:grid sm:grid-cols-[1fr_1.5fr_auto] gap-2 px-1">
        <span className="text-[10px] font-semibold text-text-muted uppercase tracking-wider">Nome</span>
        <span className="text-[10px] font-semibold text-text-muted uppercase tracking-wider">Email</span>
        <span className="w-7" />
      </div>

      {contatos.map((contato) => (
        <div key={contato.id} className="flex flex-col sm:grid sm:grid-cols-[1fr_1.5fr_auto] gap-2 items-center">
          <input
            className="form-input-base"
            value={contato.nome}
            onChange={(e) => handleUpdate(contato.id, 'nome', e.target.value)}
            placeholder="Nome do contato"
          />
          <input
            className="form-input-base"
            value={contato.email}
            onChange={(e) => handleUpdate(contato.id, 'email', e.target.value)}
            placeholder="email@exemplo.com"
          />
          {savingIds.has(contato.id) ? (
            <div className="w-7 flex items-center justify-center self-end sm:self-center">
              <Loader2 size={14} className="animate-spin text-primary" />
            </div>
          ) : (
            <button
              onClick={() => handleRemover(contato.id)}
              className="text-text-muted hover:text-danger transition p-1 rounded-md hover:bg-danger-light self-end sm:self-center"
              title="Remover contato"
            >
              <X size={14} />
            </button>
          )}
        </div>
      ))}

      <button
        onClick={handleAdicionar}
        className="inline-flex items-center gap-1.5 text-xs text-primary hover:text-primary-hover font-medium px-3 py-1.5 rounded-lg hover:bg-primary/5 transition self-start mt-1"
      >
        <Plus size={13} /> Adicionar contato
      </button>
    </div>
  )
}

