import { useState, useRef, useEffect } from 'react'
import { Bell, BellOff } from 'lucide-react'

interface Notificacao {
  id: string
  tipo: 'info' | 'warning' | 'success' | 'error'
  mensagem: string
  lida: boolean
  createdAt: string
}

// Placeholder — integrar com backend futuramente via WebSocket ou polling
const NOTIFICACOES: Notificacao[] = []

export default function NotificationCenter() {
  const [open, setOpen] = useState(false)
  const dropdownRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    if (!open) return
    const handleClick = (e: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) {
        setOpen(false)
      }
    }
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setOpen(false)
    }
    document.addEventListener('mousedown', handleClick)
    document.addEventListener('keydown', handleKey)
    return () => {
      document.removeEventListener('mousedown', handleClick)
      document.removeEventListener('keydown', handleKey)
    }
  }, [open])

  const naoLidas = NOTIFICACOES.filter((n) => !n.lida).length

  return (
    <div className="relative" ref={dropdownRef}>
      <button
        onClick={() => setOpen((prev) => !prev)}
        className="relative text-text-muted hover:text-text-primary transition p-1.5 rounded-lg hover:bg-bg-hover"
        aria-label="Notificações"
        aria-expanded={open}
        aria-haspopup="true"
        title="Notificações"
      >
        <Bell size={15} aria-hidden="true" />
        {naoLidas > 0 && (
          <span className="absolute -top-0.5 -right-0.5 w-3.5 h-3.5 bg-red-500 text-white text-[8px] font-bold rounded-full flex items-center justify-center">
            {naoLidas > 9 ? '9+' : naoLidas}
          </span>
        )}
      </button>

      {open && (
        <div
          role="menu"
          aria-label="Notificações"
          className="absolute right-0 top-full mt-2 w-80 bg-bg-card rounded-xl shadow-lg border border-border animate-fade-in-up z-[60]"
        >
          <div className="px-4 py-3 border-b border-border">
            <h3 className="text-sm font-semibold text-text-primary">Notificações</h3>
          </div>

          {NOTIFICACOES.length === 0 ? (
            <div className="px-4 py-8 text-center text-sm text-text-muted">
              <BellOff size={24} className="mx-auto mb-2 opacity-40" aria-hidden="true" />
              Nenhuma notificação
            </div>
          ) : (
            <div className="max-h-72 overflow-y-auto divide-y divide-border">
              {NOTIFICACOES.map((n) => (
                <div key={n.id} className={`px-4 py-3 text-sm ${n.lida ? 'opacity-60' : ''}`}>
                  <p className="text-text-primary">{n.mensagem}</p>
                  <p className="text-[10px] text-text-muted mt-1">{n.createdAt}</p>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  )
}

import { useRef, useState } from 'react'
import { Eye, EyeOff, Pencil, X } from 'lucide-react'

const SENTINEL = '***configurado***'
const MASKED_DISPLAY = '••••••••'

interface Props {
  label: string
  value: string
  onChange: (value: string) => void
  placeholder?: string
}

export default function PasswordConfigInput({ label, value, onChange, placeholder }: Props) {
  const isConfigured = value === SENTINEL
  const [editing, setEditing] = useState(false)
  const [showValue, setShowValue] = useState(false)
  const originalValue = useRef(value)

  // When not editing, show masked dots if configured
  if (!editing) {
    return (
      <div className="flex flex-col gap-1.5">
        <label className="text-xs font-medium text-text-muted">{label}</label>
        <div className="flex items-center gap-2">
          <div className="flex-1 flex items-center gap-2 form-input-base cursor-default">
            <span className="text-sm text-text-muted font-mono flex-1 truncate">
              {isConfigured ? MASKED_DISPLAY : (value || '—')}
            </span>
            {isConfigured && (
              <button
                type="button"
                onClick={() => { originalValue.current = value; setEditing(true); onChange(SENTINEL) }}
                className="text-xs text-primary hover:text-primary-hover font-medium transition shrink-0"
                title="Editar"
              >
                <Pencil size={13} />
              </button>
            )}
          </div>
        </div>
      </div>
    )
  }

  // Editing mode — field is empty, user types new value
  return (
    <div className="flex flex-col gap-1.5">
      <label className="text-xs font-medium text-text-muted">{label}</label>
      <div className="flex items-center gap-2">
        <div className="relative flex-1">
          <input
            type={showValue ? 'text' : 'password'}
            className="form-input-base pr-8"
            value={value === SENTINEL ? '' : value}
            onChange={(e) => {
              const v = e.target.value
              if (v !== '') onChange(v)
            }}
            placeholder={placeholder ?? 'Digite o novo valor'}
            autoFocus
          />
          <button
            onClick={() => setShowValue((prev) => !prev)}
            className="absolute right-2 top-1/2 -translate-y-1/2 text-text-muted hover:text-text-primary transition"
            title={showValue ? 'Ocultar' : 'Mostrar'}
            type="button"
          >
            {showValue ? <EyeOff size={14} /> : <Eye size={14} />}
          </button>
        </div>
        <button
          onClick={() => { setEditing(false); onChange(originalValue.current) }}
          className="text-text-muted hover:text-danger transition p-1.5 rounded-lg hover:bg-danger-light"
          title="Cancelar"
          type="button"
        >
          <X size={14} />
        </button>
      </div>
      <p className="text-[10px] text-text-muted">
        Deixe vazio para manter o valor atual
      </p>
    </div>
  )
}

import { Navigate } from 'react-router-dom'
import { useAuth } from '../hooks/useAuth'
import type { Role } from '../types'

interface ProtectedRouteProps {
  children: React.ReactNode
  allowedRoles: Role[]
}

export default function ProtectedRoute({ children, allowedRoles }: ProtectedRouteProps) {
  const { isAuthenticated, getRole } = useAuth()

  if (!isAuthenticated()) {
    return <Navigate to="/login" replace />
  }

  const role = getRole()
  if (!role || !allowedRoles.includes(role)) {
    return <Navigate to="/" replace />
  }

  return <>{children}</>
}

import { useState } from 'react'
import { AlertCircle, Loader2, CheckCircle2, XCircle } from 'lucide-react'

interface Props {
  label: string
  onTest: () => Promise<{ status: string; mensagem: string }>
  warningText?: string
}

export default function TestConnectionButton({ label, onTest, warningText }: Props) {
  const [testing, setTesting] = useState(false)
  const [result, setResult] = useState<{ ok: boolean; msg: string } | null>(null)

  async function handleTest() {
    setTesting(true)
    setResult(null)
    try {
      const res = await onTest()
      setResult({ ok: res.status === 'ok', msg: res.mensagem })
    } catch {
      setResult({ ok: false, msg: 'Erro ao testar conexão' })
    } finally {
      setTesting(false)
    }
  }

  return (
    <div className="flex flex-col gap-1.5">
      <div className="flex items-center gap-2">
        <button
          onClick={handleTest}
          disabled={testing}
          className="inline-flex items-center gap-2 text-xs font-medium text-primary hover:text-primary-hover disabled:opacity-50 transition px-3 py-1.5 rounded-lg hover:bg-primary/5 w-fit"
        >
          {testing ? <Loader2 size={13} className="animate-spin" /> : null}
          {testing ? 'Testando...' : label}
        </button>
        {warningText && (
          <span className="text-[10px] text-amber-600 dark:text-amber-400 flex items-center gap-0.5" title={warningText}>
            <AlertCircle size={11} />
            Usa config. salva
          </span>
        )}
      </div>
      {result && (
        <p className={`text-[11px] flex items-center gap-1 ${result.ok ? 'text-emerald-600 dark:text-emerald-400' : 'text-red-500'}`}>
          {result.ok ? <CheckCircle2 size={12} /> : <XCircle size={12} />}
          {result.msg}
        </p>
      )}
    </div>
  )
}

import { useToasts } from '../hooks/useToast'
import { CheckCircle, XCircle, Info, X } from 'lucide-react'

const icons: Record<string, React.ReactNode> = {
  success: <CheckCircle size={16} className="text-success" />,
  error: <XCircle size={16} className="text-danger" />,
  info: <Info size={16} className="text-info" />,
}

const bgColors: Record<string, string> = {
  success: 'bg-success-light border-success/20',
  error: 'bg-danger-light border-danger/20',
  info: 'bg-info/10 border-info/20',
}

export default function ToastContainer() {
  const { toasts, remove } = useToasts()

  if (toasts.length === 0) return null

  return (
    <div className="fixed bottom-4 lg:bottom-6 left-1/2 -translate-x-1/2 z-[100] flex flex-col gap-2 w-[90vw] max-w-sm">
      {toasts.map((toast) => (
        <div
          key={toast.id}
          className={`flex items-center gap-2 px-4 py-3 rounded-xl shadow-lg border ${bgColors[toast.type]} animate-fade-in-up`}
        >
          {icons[toast.type]}
          <p className="text-sm font-medium text-text-primary flex-1">{toast.message}</p>
          <button onClick={() => remove(toast.id)} className="text-text-muted hover:text-text-secondary transition">
            <X size={14} />
          </button>
        </div>
      ))}
    </div>
  )
}

