/** Helper to format currency on chart axes */
export function formatChartCurrency(value: number): string {
  if (value >= 1_000_000) return `R$ ${(value / 1_000_000).toFixed(1)}M`
  if (value >= 1_000) return `R$ ${(value / 1_000).toFixed(0)}k`
  return `R$ ${value.toFixed(0)}`
}

/** Helper to format plain numbers on chart axes */
export function formatChartNumber(value: number): string {
  if (value >= 1_000_000) return `${(value / 1_000_000).toFixed(1)}M`
  if (value >= 1_000) return `${(value / 1_000).toFixed(0)}k`
  return value.toFixed(0)
}

import { useCallback } from 'react'
import { jwtDecode } from 'jwt-decode'
import api from '../api/client'
import { login as apiLogin } from '../api/auth'
import { getAccessToken, setAccessToken } from '../api/tokenStore'
import type { JwtPayload, Role } from '../types'

function getToken(): string | null {
  return getAccessToken()
}

function parseJwtPayload(token: string): JwtPayload | null {
  try {
    return jwtDecode<JwtPayload>(token)
  } catch {
    return null
  }
}

function isTokenExpired(token: string): boolean {
  const payload = parseJwtPayload(token)
  if (!payload) return true

  const exp = (payload as JwtPayload & { exp?: number }).exp
  if (!exp) return false

  const now = Date.now() / 1000
  return exp < now
}

function _getTokenExp(token: string): number | null {
  const payload = parseJwtPayload(token)
  if (!payload) return null
  return (payload as JwtPayload & { exp?: number }).exp ?? null
}

function _getExpiresInMs(token: string): number {
  const exp = _getTokenExp(token)
  if (exp === null) return 0
  const remaining = exp * 1000 - Date.now()
  return Math.max(0, remaining)
}

export function useAuth() {
  const isAuthenticated = useCallback((): boolean => {
    const token = getToken()
    if (!token) return false
    if (isTokenExpired(token)) {
      return false
    }
    return true
  }, [])

  const getRole = useCallback((): Role | null => {
    const token = getToken()
    if (!token || isTokenExpired(token)) return null

    const payload = parseJwtPayload(token)
    return payload?.role ?? null
  }, [])

  const getUsername = useCallback((): string | null => {
    const token = getToken()
    if (!token) return null
    const payload = parseJwtPayload(token)
    return payload?.sub ?? null
  }, [])

  const getNomeExibicao = useCallback((): string => {
    const token = getToken()
    if (!token) return ''
    const payload = parseJwtPayload(token)
    if (!payload) return ''
    return `${payload.nome_exibicao ?? payload.sub} (${payload.role})`
  }, [])

  const login = useCallback(async (username: string, password: string) => {
    const data = await apiLogin(username, password)
    const decoded = jwtDecode<JwtPayload>(data.access_token)
    setAccessToken(data.access_token)
    return decoded.role as Role
  }, [])

  const logout = useCallback(async () => {
    let revoked = false
    try {
      await api.post('/auth/logout', {}, { timeout: 10000 })
      revoked = true
    } catch (err) {
      console.warn(
        '[Auth] Não foi possível revogar o token no servidor.',
        err
      )
    }
    setAccessToken(null)
    if (!revoked) {
      console.warn('[Auth] Token pode ainda ser válido.')
    }
  }, [])

  const checkAuth = useCallback(() => {
    const valid = isAuthenticated()
    return valid
  }, [isAuthenticated])

  const getTokenExp = useCallback((): number | null => {
    const token = getToken()
    if (!token) return null
    return _getTokenExp(token)
  }, [])

  const getExpiresInMs = useCallback((): number => {
    const token = getToken()
    if (!token) return 0
    return _getExpiresInMs(token)
  }, [])

  return { isAuthenticated, getRole, getUsername, getNomeExibicao, login, logout, checkAuth, getTokenExp, getExpiresInMs }
}

import { useState, useEffect, useRef } from 'react'

export function useCountUp(target: number, duration = 600, enabled = true): number {
  const [value, setValue] = useState(enabled ? 0 : target)
  const rafRef = useRef<number>(0)
  const prevTargetRef = useRef<number | null>(null)
  const lastValueRef = useRef<number>(0)

  useEffect(() => {
    if (!enabled || target === 0) {
      // eslint-disable-next-line react-hooks/set-state-in-effect -- Intentional: skip animation for disabled/zero targets
      setValue(target)
      lastValueRef.current = target
      prevTargetRef.current = null
      return
    }

    const start = performance.now()
    // If target changed mid-animation, start from last displayed value instead of 0
    const targetChanged = prevTargetRef.current !== null && prevTargetRef.current !== target
    const from = targetChanged ? lastValueRef.current : 0
    prevTargetRef.current = target

    function tick(now: number) {
      const elapsed = now - start
      const progress = Math.min(elapsed / duration, 1)
      const eased = 1 - Math.pow(1 - progress, 3)
      const current = from + (target - from) * eased
      setValue(current)
      lastValueRef.current = current
      if (progress < 1) {
        rafRef.current = requestAnimationFrame(tick)
      } else {
        setValue(target)
        lastValueRef.current = target
      }
    }

    rafRef.current = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(rafRef.current)
  }, [target, duration, enabled])

  return value
}

/** Hook para o módulo Intelligence — polling, cache sessionStorage, dismiss. */
import { useCallback, useRef, useState } from 'react'
import { fetchIntelligence, fetchIntelligenceStatus, dismissInsightAPI } from '../api/intelligence'
import type { IntelligenceResponse } from '../types/intelligence'

type IntelligenceStatus = 'idle' | 'loading' | 'ready' | 'error'
type IntelligenceError = { message: string } | null

const SESSION_STORAGE_KEY = 'vitrine_intelligence'
const POLLING_INTERVAL = 2000
const POLLING_TIMEOUT = 300_000 // 5 min

function setCache(data: IntelligenceResponse) {
  try {
    sessionStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify({ data, timestamp: Date.now() }))
  } catch {
    // sessionStorage cheio ou indisponível — ignora
  }
}

export function useIntelligence() {
  const [status, setStatus] = useState<IntelligenceStatus>('idle')
  const [resultado, setResultado] = useState<IntelligenceResponse | null>(null)
  const [erro, setErro] = useState<IntelligenceError>(null)
  const [jobId, setJobId] = useState<string | null>(null)
  const pollingRef = useRef<ReturnType<typeof setInterval> | null>(null)
  const controllerRef = useRef<AbortController | null>(null)

  const pararPolling = useCallback(() => {
    if (pollingRef.current) {
      clearInterval(pollingRef.current)
      pollingRef.current = null
    }
  }, [])

  const gerarAnalise = useCallback(async () => {
    // Aborta requisição anterior se houver
    controllerRef.current?.abort()
    const controller = new AbortController()
    controllerRef.current = controller
    const signal = controller.signal

    // Remove cache sessionStorage para forçar requisição ao backend
    sessionStorage.removeItem(SESSION_STORAGE_KEY)

    setStatus('loading')
    setResultado(null)
    setErro(null)
    setJobId(null)

    try {
      const data = await fetchIntelligence(signal)

      if ('job_id' in data && data.job_id) {
        // 2. Cache miss — inicia polling
        setJobId(data.job_id)
        const jobIdVal = data.job_id
        const inicio = Date.now()

        pararPolling()
        pollingRef.current = setInterval(async () => {
          try {
            const pollSignal = controller.signal
            const jobStatus = await fetchIntelligenceStatus(jobIdVal, pollSignal)

            if (jobStatus.status === 'ready' && jobStatus.resultado) {
              pararPolling()
              setResultado(jobStatus.resultado)
              setStatus('ready')
              setCache(jobStatus.resultado)
            } else if (jobStatus.status === 'error') {
              pararPolling()
              setErro({ message: jobStatus.erro || 'Análise falhou no processamento' })
              setStatus('error')
            } else if (Date.now() - inicio > POLLING_TIMEOUT) {
              pararPolling()
              setErro({ message: 'A análise excedeu o tempo limite. Tente novamente.' })
              setStatus('error')
            }
          } catch {
            // polling continua na próxima iteração
          }
        }, POLLING_INTERVAL)
      } else {
        // 3. Cache hit ou fallback — resposta já veio
        const response = data as IntelligenceResponse
        setResultado(response)
        setStatus('ready')
        setCache(response)
      }
    } catch (e: unknown) {
      const err = e as { name?: string; message?: string; response?: { status?: number; data?: { error?: string } } }
      if (err?.name === 'CanceledError' || err?.name === 'AbortError') return
      const errorMsg = err?.response?.data?.error || err?.message || 'Erro desconhecido'
      console.error('[Intelligence] fetchIntelligence failed:', err?.response?.status, errorMsg)
      setErro({ message: errorMsg })
      setStatus('error')
    }
  }, [pararPolling])

  const dismissInsight = useCallback(async (hash: string) => {
    try {
      await dismissInsightAPI(hash)
      // Remove do estado local
      setResultado(prev => prev ? {
        ...prev,
        insights: prev.insights.filter(i => i.hash !== hash),
      } : prev)
    } catch {
      // silencioso — falha no dismiss não bloqueia UX
    }
  }, [])

  return { status, resultado, erro, jobId, gerarAnalise, dismissInsight }
}

import { useState, useEffect } from 'react'

export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    try {
      const item = localStorage.getItem(key)
      return item ? JSON.parse(item) : initialValue
    } catch {
      return initialValue
    }
  })

  useEffect(() => {
    try {
      localStorage.setItem(key, JSON.stringify(value))
    } catch {
      // localStorage cheio ou desabilitado — falha silenciosa
    }
  }, [key, value])

  return [value, setValue] as const
}

/** Hook para buscar indicadores macroeconômicos do endpoint /bi/intelligence/macro. */
import { useEffect, useRef, useState } from 'react'
import api from '../api/client'
import type { MacroIndicator } from '../types/macro'

type MacroStatus = 'loading' | 'ready' | 'error'

interface UseMacroReturn {
  indicadores: MacroIndicator[]
  status: MacroStatus
  erro: string | null
}

export function useMacroIndicators(): UseMacroReturn {
  const [indicadores, setIndicadores] = useState<MacroIndicator[]>([])
  const [status, setStatus] = useState<MacroStatus>('loading')
  const [erro, setErro] = useState<string | null>(null)
  const mountedRef = useRef(true)

  useEffect(() => {
    mountedRef.current = true
    setStatus('loading')

    api.get('/bi/intelligence/macro')
      .then(res => {
        if (!mountedRef.current) return
        const data = res.data as MacroIndicator[]
        setIndicadores(data)
        setStatus('ready')
      })
      .catch((e: unknown) => {
        if (!mountedRef.current) return
        const err = e as { message?: string; response?: { data?: { error?: string } } }
        const msg = err?.response?.data?.error || err?.message || 'Erro ao carregar indicadores'
        setErro(msg)
        setStatus('error')
      })

    return () => { mountedRef.current = false }
  }, [])

  return { indicadores, status, erro }
}

import { useState, useEffect, useRef, useCallback } from 'react'
import { fetchTabelaProdutos } from '../api/bi'
import type { ProdutoTabelaResponse, SortByProduto } from '../types'

export function useTabelaProdutos() {
  const [items, setItems] = useState<ProdutoTabelaResponse[]>([])
  const [total, setTotal] = useState(0)
  const [loading, setLoading] = useState(true)
  const [erro, setErro] = useState<string | null>(null)

  const [search, setSearch] = useState('')
  const [grupo, setGrupo] = useState('')
  const [familia, setFamilia] = useState('')

  const [sortBy, setSortBy] = useState<SortByProduto>('nome')
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('asc')

  const [page, setPage] = useState(0)
  const [pageSize, setPageSize] = useState(50)

  const [filtrosDisponiveis, setFiltros] = useState<{ grupos: string[]; familias: string[] }>({
    grupos: [],
    familias: [],
  })

  const searchTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  const mountedRef = useRef(true)

  useEffect(() => {
    mountedRef.current = true
    return () => { mountedRef.current = false }
  }, [])

  const fetchData = useCallback(async () => {
    setLoading(true)
    setErro(null)
    try {
      const data = await fetchTabelaProdutos({
        grupo: grupo || undefined,
        familia: familia || undefined,
        search: search || undefined,
        sort_by: sortBy,
        sort_order: sortOrder,
        limit: pageSize,
        offset: page * pageSize,
      })
      if (!mountedRef.current) return
      setItems(data.items)
      setTotal(data.total)
      if (data.filtros_disponiveis) {
        setFiltros(data.filtros_disponiveis)
      }
    } catch (err) {
      if (!mountedRef.current) return
      setErro('Erro ao carregar tabela de preços.')
      console.error('Erro fetchTabelaProdutos:', err)
    } finally {
      if (mountedRef.current) setLoading(false)
    }
  }, [grupo, familia, search, sortBy, sortOrder, page, pageSize])

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect -- Intentional: data fetching on dependency change (setState calls are async after await)
    fetchData()
  }, [fetchData])

  const setSearchDebounced = useCallback((value: string) => {
    if (searchTimer.current) clearTimeout(searchTimer.current)
    searchTimer.current = setTimeout(() => {
      setSearch(value)
      setPage(0)
    }, 300)
  }, [])

  const totalPages = Math.ceil(total / pageSize)

  return {
    items, total, loading, erro,
    search, setSearch: setSearchDebounced,
    grupo, setGrupo, familia, setFamilia,
    sortBy, setSortBy, sortOrder, setSortOrder,
    page, setPage, pageSize, setPageSize,
    filtrosDisponiveis, totalPages, fetchData,
  }
}

/* eslint-disable react-refresh/only-export-components -- Hook + Context + Provider must coexist in one file to avoid circular imports and breaking 10+ consumers */
import { createContext, useContext, useState, useCallback, type ReactNode } from 'react'

type ToastType = 'success' | 'error' | 'info'

interface ToastMessage {
  id: number
  type: ToastType
  message: string
}

interface ToastContextType {
  toasts: ToastMessage[]
  toast: (msg: Omit<ToastMessage, 'id'>) => void
  remove: (id: number) => void
}

const ToastContext = createContext<ToastContextType | null>(null)

let nextId = 0

const durations: Record<ToastType, number> = {
  success: 3000,
  error: 6000,
  info: 4000,
}

export function ToastProvider({ children }: { children: ReactNode }) {
  const [toasts, setToasts] = useState<ToastMessage[]>([])

  const toastFn = useCallback((msg: Omit<ToastMessage, 'id'>) => {
    const id = nextId++
    setToasts(prev => [...prev, { ...msg, id }])
    setTimeout(() => {
      setToasts(prev => prev.filter(t => t.id !== id))
    }, durations[msg.type])
  }, [])

  const remove = useCallback((id: number) => {
    setToasts(prev => prev.filter(t => t.id !== id))
  }, [])

  return (
    <ToastContext.Provider value={{ toasts, toast: toastFn, remove }}>
      {children}
    </ToastContext.Provider>
  )
}

export function useToast() {
  const ctx = useContext(ToastContext)
  if (!ctx) throw new Error('useToast must be used within ToastProvider')
  return { toast: ctx.toast }
}

export function useToasts() {
  const ctx = useContext(ToastContext)
  if (!ctx) throw new Error('useToasts must be used within ToastProvider')
  return ctx
}

