/* ═══════════════════════════════════════════════════════════════════════════
   ANIMATIONS
════════════════════════════════════════════════════════════════════════════ */

@keyframes fade-in-up {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes pulse-glow {
  0%, 100% { box-shadow: 0 0 0 0 rgba(5, 150, 105, 0.4); }
  50% { box-shadow: 0 0 0 12px rgba(5, 150, 105, 0); }
}

@keyframes slide-up {
  from { opacity: 0; transform: translateY(100%); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes scale-in {
  from { opacity: 0; transform: scale(0.95); }
  to { opacity: 1; transform: scale(1); }
}

@keyframes page-fade-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes fade-out {
  from { opacity: 1; }
  to { opacity: 0; }
}

@keyframes slide-down {
  from { opacity: 1; transform: translateY(0); }
  to { opacity: 0; transform: translateY(20px); }
}

@keyframes highlight-pulse {
  0%, 100% { background-color: transparent; }
  50% { background-color: var(--color-primary); opacity: 0.08; }
}

/* ── Premium glow animations ── */
@keyframes glow-danger {
  0%, 100% { box-shadow: 0 0 12px color-mix(in srgb, var(--color-danger) 15%, transparent), 0 0 40px color-mix(in srgb, var(--color-danger) 5%, transparent); }
  50% { box-shadow: 0 0 20px color-mix(in srgb, var(--color-danger) 25%, transparent), 0 0 60px color-mix(in srgb, var(--color-danger) 8%, transparent); }
}
@keyframes glow-warning {
  0%, 100% { box-shadow: 0 0 12px color-mix(in srgb, var(--color-warning) 12%, transparent), 0 0 40px color-mix(in srgb, var(--color-warning) 4%, transparent); }
  50% { box-shadow: 0 0 20px color-mix(in srgb, var(--color-warning) 20%, transparent), 0 0 60px color-mix(in srgb, var(--color-warning) 6%, transparent); }
}
@keyframes glow-info {
  0%, 100% { box-shadow: 0 0 12px color-mix(in srgb, var(--color-info) 10%, transparent), 0 0 40px color-mix(in srgb, var(--color-info) 3%, transparent); }
  50% { box-shadow: 0 0 20px color-mix(in srgb, var(--color-info) 18%, transparent), 0 0 60px color-mix(in srgb, var(--color-info) 5%, transparent); }
}
@keyframes status-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}

/* Utility classes */
.animate-fade-in-up { animation: fade-in-up 0.5s ease-out both; }
.animate-pulse-glow { animation: pulse-glow 0.8s ease-out; }
.animate-slide-up { animation: slide-up 0.3s ease-out; }
.animate-scale-in { animation: scale-in 0.4s ease-out both; }
.animate-page-in { animation: page-fade-in 0.3s ease-out both; }
.animate-fade-out { animation: fade-out 0.2s ease-in both; }
.animate-slide-down { animation: slide-down 0.2s ease-in both; }
.animate-highlight-pulse { animation: highlight-pulse 1.5s ease-out; }
.animate-glow-danger { animation: glow-danger 3s ease-in-out infinite; }
.animate-glow-warning { animation: glow-warning 3s ease-in-out infinite; }
.animate-glow-info { animation: glow-info 3s ease-in-out infinite; }
.animate-status-pulse { animation: status-pulse 2s ease-in-out infinite; }

/* Card hover lift — reutilizável */
.card-hover {
  transition: transform var(--duration-fast) var(--ease-out),
              box-shadow var(--duration-fast) var(--ease-out);
}
.card-hover:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-card-hover);
}

/* Hero card — para a seção de resumo executivo premium */
.hero-card {
  background: linear-gradient(135deg, 
    color-mix(in srgb, var(--color-primary) 8%, transparent) 0%, 
    color-mix(in srgb, var(--color-info) 4%, transparent) 50%,
    transparent 100%);
  border: 1px solid color-mix(in srgb, var(--color-primary) 12%, transparent);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-card), 
              0 0 40px color-mix(in srgb, var(--color-primary) 5%, transparent);
}

/* Focus ring refinement */
input:focus, select:focus, textarea:focus, button:focus-visible {
  outline: none;
}

