  label: string
  value: string
  trend?: string
  color?: string
}) {
  return (
    <div className="bg-bg-hover/30 rounded-xl p-3 sm:p-4 border border-border/20 hover:border-border/40 transition-colors">
      <div className="flex items-center gap-2 mb-1.5">
