        </div>

        {/* ── Macro Indicators Strip ── */}
        <MacroStrip
          indicadores={macroIndicadores}
          loading={macroStatus === 'loading'}
          erro={macroErro}
        />

        {/* ── Loading ── */}
        {status === 'loading' && (
          <div className="space-y-4">
            <Skeleton className="h-32 w-full rounded-xl" />
