import { subMonths, startOfMonth, endOfMonth, format } from 'date-fns'
import PeriodoForm, { type Preset } from '../../components/bi/PeriodoForm'
import BiPageLayout from '../../components/bi/BiPageLayout'
import ExportButtons from '../../components/bi/ExportButtons'
import BiTooltip from '../../components/bi/BiTooltip'
import EmptyState from '../../components/ui/EmptyState'
import ErrorBanner from '../../components/ui/ErrorBanner'
import Card from '../../components/ui/Card'
import SectionHeader from '../../components/ui/SectionHeader'
import DataTable from '../../components/ui/DataTable'
import type { Column } from '../../components/ui/DataTable'
import { fetchReceita, fetchQuantidade, exportarExcelBI } from '../../api/bi'
import { baixarCSVdeArray } from '../../utils/csv'
import type { ItemDimensaoDTO, PeriodoBi, Dimensao, Metrica } from '../../types'
import { formatCurrency } from '../../utils/formatters'
import { CHART } from '../../utils/colors'
import { useBiCache } from '../../stores/biCache'
import { useToast } from '../../hooks/useToast'
import { BarChart3 } from 'lucide-react'
import Skeleton from '../../components/ui/Skeleton'
import {
  BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid,
} from 'recharts'

const PRESETS_RECEITA: Preset[] = [
  { label: '7 dias', kind: 'days', days: 7 },
  { label: '30 dias', kind: 'days', days: 30 },
  { label: 'Este mês', kind: 'current_month' },
  { label: 'Mês passado', kind: 'last_month' },
]

function periodoInicial(): PeriodoBi {
  const mesPassado = subMonths(new Date(), 1)
  return {
    data_inicio: format(startOfMonth(mesPassado), 'yyyy-MM-dd'),
    data_fim: format(endOfMonth(mesPassado), 'yyyy-MM-dd'),
  }
}

function labelDimensao(item: ItemDimensaoDTO, dimensao: Dimensao): string {
  if (dimensao === 'produto') return item.produto ?? item.familia ?? item.grupo
  if (dimensao === 'familia') return item.familia ?? item.grupo
  return item.grupo
}

export default function Receita() {
  const [searchParams, setSearchParams] = useSearchParams()
  const [periodo, setPeriodo] = useState<PeriodoBi>(periodoInicial)
  const [dimensao, setDimensao] = useState<Dimensao>(
    (searchParams.get('dimensao') as Dimensao) ?? 'produto'
  )
  const [metrica, setMetrica] = useState<Metrica>(
    (searchParams.get('metrica') as Metrica) ?? 'receita_produto'
  )
  const [filtroGrupo, setFiltroGrupo] = useState('')
  const [filtroFamilia, setFiltroFamilia] = useState('')
  const [dados, setDados] = useState<ItemDimensaoDTO[]>([])
  const [loading, setLoading] = useState(false)
  const [erro, setErro] = useState<string | null>(null)
  const navigate = useNavigate()
  const cache = useBiCache()
  const { toast } = useToast()

  const cacheKey = `receita_${dimensao}_${metrica}`

  const buscar = useCallback(async (periodoOverride?: PeriodoBi, force = false, signal?: AbortSignal) => {
    const p = periodoOverride ?? periodo
    if (!force) {
      const cached = cache.get<ItemDimensaoDTO[]>(cacheKey, p)
      if (cached) { setDados(cached); return }
    }
    setErro(null)
    setLoading(true)
    try {
      const data = metrica === 'receita_produto'
        ? await fetchReceita(p, dimensao, signal)
        : await fetchQuantidade(p, dimensao, signal)
      setDados(data)
      cache.set(cacheKey, p, data)
    } catch (e: unknown) {
      const err = e as { response?: { status?: number; data?: { detail?: string } }; name?: string }
      if (err?.name === 'CanceledError' || err?.name === 'AbortError') return
      if (err.response?.status === 400) setErro(err.response.data?.detail ?? 'Erro ao carregar dados.')
      else setErro('Erro ao carregar dados.')
    } finally {
      setLoading(false)
    }
  }, [periodo, dimensao, metrica, cache]) // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    const controller = new AbortController()
    const signal = controller.signal
    const t = setTimeout(() => buscar(undefined, undefined, signal))
    return () => { clearTimeout(t); controller.abort() }
  }, [buscar])

  function handleBuscar(periodoOverride?: PeriodoBi) {
    cache.invalidate(cacheKey)
    buscar(periodoOverride, true)
  }

  function syncParams(d: Dimensao, m: Metrica) {
    const next = new URLSearchParams()
    if (d !== 'produto') next.set('dimensao', d)
    if (m !== 'receita_produto') next.set('metrica', m)
    setSearchParams(next, { replace: true })
  }

  const grupos = useMemo(() => {
    if (dimensao === 'grupo') return [] as string[]
    return [...new Set(dados.map(d => d.grupo))].sort()
  }, [dados, dimensao])

  const familias = useMemo(() => {
    if (!filtroGrupo || dimensao !== 'produto') return [] as string[]
    return [...new Set(dados.filter(d => d.grupo === filtroGrupo).map(d => d.familia).filter((f): f is string => f != null))].sort()
  }, [dados, filtroGrupo, dimensao])

  const dadosFiltrados = useMemo(() => {
    if (dimensao === 'grupo') return dados
    return dados.filter(d => {
      if (filtroGrupo && d.grupo !== filtroGrupo) return false
      if (filtroFamilia && d.familia !== filtroFamilia) return false
      return true
    })
  }, [dados, dimensao, filtroGrupo, filtroFamilia])

  const isReceita = metrica === 'receita_produto'
  const top10 = dadosFiltrados.slice(0, 10).map((item) => ({
    label: labelDimensao(item, dimensao),
    valor: item.valor,
  }))

  function buildReceitaColumns(): Column<ItemDimensaoDTO>[] {
    const cols: Column<ItemDimensaoDTO>[] = [
      { key: 'grupo', label: 'Grupo', render: (item) => <span className="truncate block" title={item.grupo}>{item.grupo}</span> },
    ]
    if (dimensao !== 'grupo') {
      cols.push({
        key: 'familia', label: 'Família',
        render: (item) => <span className="truncate block text-text-muted" title={item.familia ?? ''}>{item.familia ?? '\u2014'}</span>,
      })
    }
    if (dimensao === 'produto') {
      cols.push({
        key: 'produto', label: 'Produto',
        render: (item) => <span className="truncate block" title={item.produto ?? ''}>{item.produto ?? '\u2014'}</span>,
      })
    }
    cols.push({
      key: 'valor', label: isReceita ? 'Receita' : 'Quantidade', align: 'right', mono: true,
      render: (item) => <span className="font-semibold">{isReceita ? formatCurrency(item.valor) : item.valor.toLocaleString('pt-BR')}</span>,
    })
    return cols
  }

  return (
    <BiPageLayout titulo="Receita por Dimensão" breadcrumb={[{ label: 'BI', path: '/bi' }, { label: 'Receita' }]}>
      <Card variant="bordered">
        <div className="flex flex-col gap-4">
          <PeriodoForm value={periodo} onChange={setPeriodo} onBuscar={handleBuscar} loading={loading} presets={PRESETS_RECEITA} />
          <div className="flex gap-4 flex-wrap">
            <div className="flex flex-col gap-1">
              <label className="text-xs text-text-muted">Dimensão</label>
              <select
                className="form-input-base"
                value={dimensao}
                onChange={(e) => { const val = e.target.value as Dimensao; setDimensao(val); syncParams(val, metrica) }}
              >
                <option value="grupo">Grupo</option>
                <option value="familia">Família</option>
                <option value="produto">Produto</option>
              </select>
            </div>
            <div className="flex flex-col gap-1">
              <label className="text-xs text-text-muted">Métrica</label>
              <select
                className="form-input-base"
                value={metrica}
                onChange={(e) => { const val = e.target.value as Metrica; setMetrica(val); syncParams(dimensao, val) }}
              >
                <option value="receita_produto">Receita</option>
                <option value="qtd_item">Quantidade</option>
              </select>
            </div>
          </div>
          {dimensao !== 'grupo' && (
            <div className="flex gap-4 flex-wrap">
              <div className="flex flex-col gap-1">
                <label className="text-xs text-text-muted">Grupo</label>
              <select
                className="form-input-base"
                value={filtroGrupo}
                  onChange={(e) => { setFiltroGrupo(e.target.value); setFiltroFamilia('') }}
                >
                  <option value="">Todos</option>
                  {grupos.map(g => <option key={g} value={g}>{g}</option>)}
                </select>
              </div>
              {dimensao === 'produto' && filtroGrupo && (
                <div className="flex flex-col gap-1">
                  <label className="text-xs text-text-muted">Família</label>
                  <select
                    className="form-input-base"
                    value={filtroFamilia}
                    onChange={(e) => setFiltroFamilia(e.target.value)}
                  >
                    <option value="">Todas</option>
                    {familias.map(f => <option key={f} value={f}>{f}</option>)}
                  </select>
                </div>
              )}
            </div>
          )}
          {erro && <ErrorBanner message={erro} />}
          <ExportButtons
            onExcel={() => { exportarExcelBI(periodo, metrica === 'receita_produto' ? 'receita' : 'quantidade', { dimensao }); toast({ type: 'success', message: 'Excel exportado' }) }}
            onCsv={() => { baixarCSVdeArray(dados, metrica === 'receita_produto' ? 'receita' : 'quantidade'); toast({ type: 'success', message: 'CSV exportado' }) }}
            disabled={dados.length === 0}
          />
        </div>
      </Card>

      {loading && !dados.length && (
        <Card variant="bordered">
          <Skeleton className="h-5 w-40 mb-4" />
          <Skeleton variant="chart" />
        </Card>
      )}
      {!loading && dados.length === 0 && (
        <EmptyState title="Nenhum dado no período" description="Tente ampliar o período ou alterar os filtros." />
      )}
      {dados.length > 0 && dadosFiltrados.length === 0 && (
        <EmptyState title="Nenhum resultado para os filtros" description="Tente limpar os filtros de grupo ou família." />
      )}
      {dados.length > 0 && dadosFiltrados.length > 0 && (
        <>
          <Card variant="bordered">
            <SectionHeader icon={BarChart3}>Top 10</SectionHeader>
            <div className="w-full aspect-[16/9] md:aspect-[21/9]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={top10} layout="vertical" margin={{ top: 0, right: 16, left: 8, bottom: 0 }}>
                <defs>
                  <linearGradient id="barGradientReceita" x1="0" y1="0" x2="1" y2="0">
                    <stop offset="0%" stopColor={CHART.green} stopOpacity={0.9} />
                    <stop offset="100%" stopColor={CHART.green} stopOpacity={0.25} />
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="#e5e7eb" />
                <XAxis type="number" tick={{ fontSize: 11, fill: 'var(--color-text-muted)' }} axisLine={{ stroke: 'var(--color-border)' }} tickLine={false} tickFormatter={(v) => isReceita ? `${(v / 1000).toFixed(0)}k` : v} />
                <YAxis type="category" dataKey="label" width={120} tick={{ fontSize: 11, fill: 'var(--color-text-muted)' }} axisLine={false} tickLine={false} />
                <Tooltip content={<BiTooltip />} cursor={{ fill: 'rgba(100,100,100,0.06)' }} />
                <Bar dataKey="valor" fill="url(#barGradientReceita)" radius={[0, 4, 4, 0]} animationBegin={0} animationDuration={600} />
              </BarChart>
            </ResponsiveContainer>
            </div>
          </Card>

          <Card variant="bordered">
            <SectionHeader>
              Todos os resultados <span className="text-text-muted font-normal">({dadosFiltrados.length})</span>
            </SectionHeader>
            <DataTable
              data={dadosFiltrados}
              columns={buildReceitaColumns()}
              rowKey={(item) => `${item.grupo}-${item.familia ?? ''}-${item.produto ?? ''}`}
              onRowClick={(item) => item.codigo && navigate(`/bi/sku?codigo=${item.codigo}`)}
              density="sm"
              stickyHeader
            />
          </Card>
        </>
      )}
    </BiPageLayout>
  )
}

import { useState, useCallback, useEffect, useRef } from 'react'
import { useSearchParams } from 'react-router-dom'
import { subDays, format } from 'date-fns'
import PeriodoForm, { type Preset } from '../../components/bi/PeriodoForm'
import BiPageLayout from '../../components/bi/BiPageLayout'
import ExportButtons from '../../components/bi/ExportButtons'
import BiTooltip from '../../components/bi/BiTooltip'
import EmptyState from '../../components/ui/EmptyState'
import ErrorBanner from '../../components/ui/ErrorBanner'
import Card from '../../components/ui/Card'
import SectionHeader from '../../components/ui/SectionHeader'
import DataTable from '../../components/ui/DataTable'
import KpiCard from '../../components/bi/KpiCard'
import { fetchSku, exportarExcelBI } from '../../api/bi'
import { buscarProdutosPorNome } from '../../api/produtos'
import { baixarCSVdeArray } from '../../utils/csv'
import type { SkuDTO, PeriodoBi, ProdutoBasico } from '../../types'
import { formatCurrency, formatDateWithWeekday } from '../../utils/formatters'
import { CHART } from '../../utils/colors'
import { useBiCache } from '../../stores/biCache'
import { useToast } from '../../hooks/useToast'
import { useCountUp } from '../../hooks/useCountUp'
import { Search, TrendingUp, BarChart3, Calendar, Crown } from 'lucide-react'
import Skeleton from '../../components/ui/Skeleton'
import {
  AreaChart, Area, BarChart, Bar, XAxis, YAxis, Tooltip,
  ResponsiveContainer, CartesianGrid,
} from 'recharts'

const PRESETS_SKU: Preset[] = [
  { label: '7 dias', kind: 'days', days: 7 },
  { label: '30 dias', kind: 'days', days: 30 },
  { label: 'Este mês', kind: 'current_month' },
]

function periodoInicial(): PeriodoBi {
  return {
    data_inicio: format(subDays(new Date(), 30), 'yyyy-MM-dd'),
    data_fim: format(new Date(), 'yyyy-MM-dd'),
  }
}

export default function Sku() {
  const [searchParams, setSearchParams] = useSearchParams()
  const [periodo, setPeriodo] = useState<PeriodoBi>(periodoInicial)
  const [codigo, setCodigo] = useState(searchParams.get('codigo') ?? '')
  const codigoRef = useRef(codigo)
  useEffect(() => { codigoRef.current = codigo }, [codigo])
  const [dados, setDados] = useState<SkuDTO | null>(null)
  const [loading, setLoading] = useState(false)
  const [erro, setErro] = useState<string | null>(null)
  const [searchQuery, setSearchQuery] = useState('')
  const [searchResults, setSearchResults] = useState<ProdutoBasico[]>([])
  const [produtoNome, setProdutoNome] = useState('')
  const searchTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  const cache = useBiCache()
  const { toast } = useToast()

  const animReceita = useCountUp(dados?.receita_total ?? 0, 600, !!dados)
  const animQtd = useCountUp(dados?.qtd_total ?? 0, 600, !!dados)
  const animTickets = useCountUp(dados?.qtd_tickets ?? 0, 600, !!dados)
  const animTicketMedio = useCountUp(dados?.ticket_medio ?? 0, 600, !!dados)

  useEffect(() => {
    if (searchTimer.current) clearTimeout(searchTimer.current)
    const q = searchQuery.trim()
    searchTimer.current = setTimeout(async () => {
      if (q.length < 2) { setSearchResults([]); return }
      try {
        const data = await buscarProdutosPorNome(q)
        setSearchResults(data)
      } catch { setSearchResults([]) }
    }, 300)
    return () => { if (searchTimer.current) clearTimeout(searchTimer.current) }
  }, [searchQuery])

  const buscar = useCallback(async (codigoParam?: string, periodoOverride?: PeriodoBi, force = false, signal?: AbortSignal) => {
    const p = periodoOverride ?? periodo
    const valor = (codigoParam ?? codigoRef.current).trim()
    if (!valor) return
    const cacheKey = `sku_${valor}`
    if (!force) {
      const cached = cache.get<SkuDTO>(cacheKey, p)
      if (cached) { setDados(cached); return }
    }
    setErro(null)
    setLoading(true)
    try {
      const data = await fetchSku(p, valor, signal)
      setDados(data)
      cache.set(cacheKey, p, data)
    } catch (e: unknown) {
      const err = e as { response?: { status?: number }; name?: string }
      if (err?.name === 'CanceledError' || err?.name === 'AbortError') return
      if (err.response?.status === 400) setErro('Código inválido.')
      else if (err.response?.status === 404) setErro('Produto não encontrado no período informado.')
      else setErro('Erro ao carregar dados.')
      setDados(null)
    } finally {
      setLoading(false)
    }
  }, [periodo, cache])

  // Auto-search on mount if codigo present in URL — enables direct /bi/sku?codigo=XXX
  // Also reacts to URL param changes for navigation between SKUs
  // ?force=1 bypasses cache (used from header search bar)
  useEffect(() => {
    const controller = new AbortController()
    const signal = controller.signal
    const codigoParam = searchParams.get('codigo')
    const forceParam = searchParams.get('force') === '1'
    if (codigoParam && codigoParam !== codigoRef.current) {
      setCodigo(codigoParam)
    }
    if (codigoParam) {
      buscar(codigoParam, undefined, forceParam, signal)
    }
    return () => controller.abort()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [searchParams.get('codigo'), searchParams.get('force')])

  function handleBuscar(periodoOverride?: PeriodoBi) {
    const valor = codigoRef.current.trim()
    if (valor) cache.invalidate(`sku_${valor}`)
    buscar(undefined, periodoOverride, true)
  }

  return (
    <BiPageLayout titulo="Análise de SKU" breadcrumb={[{ label: 'BI', path: '/bi' }, { label: 'SKU' }]}>
      <Card variant="bordered">
        <div className="flex flex-col gap-4">
          <PeriodoForm value={periodo} onChange={setPeriodo} onBuscar={handleBuscar} loading={loading} presets={PRESETS_SKU} />
          <div>
            <div className="relative">
              <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-text-muted pointer-events-none" />
              <input
                className="form-input-base !pl-9"
                placeholder="Buscar produto por nome..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
            </div>
            {searchResults.length > 0 && (
              <div className="mt-1 bg-bg-card rounded-lg shadow-md border border-border divide-y divide-border max-h-48 overflow-y-auto absolute left-0 right-0 z-20">
                {searchResults.map((p) => (
                  <button
                    key={p.codigo_chamada}
                    onClick={() => {
                      setCodigo(p.codigo_chamada)
                      setProdutoNome(p.nome)
                      setSearchQuery('')
                      setSearchResults([])
                      setSearchParams({ codigo: p.codigo_chamada })
                      buscar(p.codigo_chamada)
                    }}
                    className="w-full text-left px-3 py-2 hover:bg-bg-hover transition text-sm flex justify-between items-center"
                  >
                    <span className="font-medium text-text-primary">{p.nome}</span>
                    <span className="text-text-muted text-xs">{p.codigo_chamada}</span>
                  </button>
                ))}
              </div>
            )}
            {produtoNome && !searchQuery && (
              <p className="mt-1 text-sm text-primary font-medium">{produtoNome}</p>
            )}
          </div>

          {erro && <ErrorBanner message={erro} />}
          <ExportButtons
            onExcel={() => { exportarExcelBI(periodo, 'sku', { codigo }); toast({ type: 'success', message: 'Excel exportado' }) }}
            onCsv={() => {
              if (!dados) return
              const linhas = dados.ranking_dias.map((d) => ({ data: d.data, receita: d.valor }))
              if (baixarCSVdeArray(linhas, 'sku')) {
                toast({ type: 'success', message: 'CSV exportado' })
              } else {
                toast({ type: 'info', message: 'Nenhum dado para exportar' })
              }
            }}
            disabled={!dados}
          />
        </div>
      </Card>

      {loading && !dados && (
        <div className="flex flex-col gap-4">
          <Skeleton variant="kpi" className="h-28" />
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
            {Array.from({ length: 4 }).map((_, i) => (
              <Skeleton key={i} variant="kpi" />
            ))}
          </div>
        </div>
      )}
      {!loading && !dados && !erro && (
        <EmptyState title="Busque um produto" description="Digite o nome ou código de um produto para analisar." />
      )}
      {dados && (
        <>
          <div className="flex flex-col gap-3">
          <Card variant="bordered">
            <p className="text-xs text-text-muted font-medium mb-1">{dados.grupo} · {dados.familia}</p>
            <p className="text-xl font-bold text-text-primary">{dados.produto}</p>
            <p className="text-sm text-text-muted font-mono mt-1">{dados.codigo}</p>
          </Card>

          <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
            <KpiCard label="Receita Total" valor={formatCurrency(animReceita)} />
            <KpiCard label="Qtd. Vendida" valor={animQtd.toLocaleString('pt-BR')} />
            <KpiCard label="Tickets" valor={animTickets.toLocaleString('pt-BR')} />
            <KpiCard label="Ticket Médio" valor={formatCurrency(animTicketMedio)} />
          </div>
          </div>

          {dados.ranking_dias.length > 0 && (
            <Card variant="bordered">
              <SectionHeader icon={TrendingUp}>Receita diária</SectionHeader>
              <div className="w-full aspect-[16/9] md:aspect-[21/9]">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart
                  data={dados.ranking_dias.slice().sort((a, b) => a.data.localeCompare(b.data))}
                  margin={{ top: 0, right: 8, left: 0, bottom: 0 }}
                >
                  <defs>
                    <linearGradient id="areaGradientSku" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="0%" stopColor={CHART.green} stopOpacity={0.3} />
                      <stop offset="100%" stopColor={CHART.green} stopOpacity={0.02} />
                    </linearGradient>
                  </defs>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="var(--color-border)" />
                  <XAxis dataKey="data" tick={{ fontSize: 11, fill: 'var(--color-text-muted)' }} tickFormatter={(v) => v.slice(5)} interval="preserveStartEnd" axisLine={{ stroke: 'var(--color-border)' }} tickLine={false} />
                  <YAxis tick={{ fontSize: 11, fill: 'var(--color-text-muted)' }} tickFormatter={(v) => `${(v / 1000).toFixed(0)}k`} width={36} axisLine={false} tickLine={false} />
                  <Tooltip content={<BiTooltip />} cursor={{ fill: 'rgba(100,100,100,0.06)' }} labelFormatter={(l) => `Data: ${l}`} />
                  <Area type="monotone" dataKey="valor" stroke={CHART.green} strokeWidth={2} fill="url(#areaGradientSku)" animationBegin={0} animationDuration={600} />
                </AreaChart>
              </ResponsiveContainer>
              </div>
            </Card>
          )}

          {dados.distribuicao_hora.length > 0 && (
            <Card variant="bordered">
              <SectionHeader icon={BarChart3}>Receita por hora</SectionHeader>
              <div className="w-full aspect-[16/9] md:aspect-[21/9]">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={dados.distribuicao_hora.map((d) => ({ label: `${d.hora}h`, valor: d.valor }))} margin={{ top: 0, right: 8, left: 0, bottom: 0 }}>
                  <defs>
                    <linearGradient id="barGradientSkuHora" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="0%" stopColor={CHART.green} stopOpacity={0.9} />
                      <stop offset="100%" stopColor={CHART.green} stopOpacity={0.25} />
                    </linearGradient>
                  </defs>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="var(--color-border)" />
                  <XAxis dataKey="label" tick={{ fontSize: 11, fill: 'var(--color-text-muted)' }} axisLine={{ stroke: 'var(--color-border)' }} tickLine={false} />
                  <YAxis tick={{ fontSize: 11, fill: 'var(--color-text-muted)' }} tickFormatter={(v) => `${(v / 1000).toFixed(0)}k`} width={36} axisLine={false} tickLine={false} />
                  <Tooltip content={<BiTooltip />} cursor={{ fill: 'rgba(100,100,100,0.06)' }} />
                  <Bar dataKey="valor" fill="url(#barGradientSkuHora)" radius={[4, 4, 0, 0]} animationBegin={0} animationDuration={600} />
                </BarChart>
              </ResponsiveContainer>
              </div>
            </Card>
          )}

          {dados.distribuicao_dia_semana.length > 0 && (
            <Card variant="bordered">
              <SectionHeader icon={Calendar}>Receita por dia da semana</SectionHeader>
              <div className="w-full aspect-[16/9] md:aspect-[21/9]">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={dados.distribuicao_dia_semana.map((d) => ({ label: d.dia_semana, valor: d.valor }))}
                  margin={{ top: 0, right: 8, left: 0, bottom: 0 }}
                >
                  <defs>
                    <linearGradient id="barGradientSkuDia" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="0%" stopColor={CHART.green} stopOpacity={0.9} />
                      <stop offset="100%" stopColor={CHART.green} stopOpacity={0.25} />
                    </linearGradient>
                  </defs>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="var(--color-border)" />
                  <XAxis dataKey="label" tick={{ fontSize: 11, fill: 'var(--color-text-muted)' }} axisLine={{ stroke: 'var(--color-border)' }} tickLine={false} />
                  <YAxis tick={{ fontSize: 11, fill: 'var(--color-text-muted)' }} tickFormatter={(v) => `${(v / 1000).toFixed(0)}k`} width={36} axisLine={false} tickLine={false} />
                  <Tooltip content={<BiTooltip />} cursor={{ fill: 'rgba(100,100,100,0.06)' }} />
                  <Bar dataKey="valor" fill="url(#barGradientSkuDia)" radius={[4, 4, 0, 0]} animationBegin={0} animationDuration={600} />
                </BarChart>
              </ResponsiveContainer>
              </div>
            </Card>
          )}

          <Card variant="bordered">
            <SectionHeader icon={Crown}>Top dias de venda</SectionHeader>
            <DataTable
              data={dados.ranking_dias}
              columns={[
                { key: 'data', label: 'Data', render: (item) => formatDateWithWeekday(item.data) },
                { key: 'valor', label: 'Receita', align: 'right', mono: true, render: (item) => <span className="font-semibold">{formatCurrency(item.valor)}</span> },
              ]}
              rowKey={(item) => item.data}
              density="sm"
              rowNumbers
            />
          </Card>
        </>
      )}
    </BiPageLayout>
  )
}

import { useState, useCallback, useEffect } from 'react'
import { subDays, format } from 'date-fns'
import PeriodoForm, { type Preset } from '../../components/bi/PeriodoForm'
import BiPageLayout from '../../components/bi/BiPageLayout'
import ExportButtons from '../../components/bi/ExportButtons'
import BiTooltip from '../../components/bi/BiTooltip'
import EmptyState from '../../components/ui/EmptyState'
import ErrorBanner from '../../components/ui/ErrorBanner'
import Card from '../../components/ui/Card'
import { fetchTemporalHora, fetchTemporalDiaSemana, exportarExcelBI } from '../../api/bi'
import { baixarCSVdeArray } from '../../utils/csv'
import type { PontoHoraDTO, PontoDiaSemanaDTO, PeriodoBi, Metrica } from '../../types'
import { CHART } from '../../utils/colors'
import { useBiCache } from '../../stores/biCache'
import { useToast } from '../../hooks/useToast'
import { Clock } from 'lucide-react'
import Skeleton from '../../components/ui/Skeleton'
import {
  BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid,
} from 'recharts'

const PRESETS_TEMPORAL: Preset[] = [
  { label: '7 dias', kind: 'days', days: 7 },
  { label: '30 dias', kind: 'days', days: 30 },
]

function periodoInicial(): PeriodoBi {
  return {
    data_inicio: format(subDays(new Date(), 7), 'yyyy-MM-dd'),
    data_fim: format(new Date(), 'yyyy-MM-dd'),
  }
}

type Aba = 'hora' | 'dia_semana'

export default function Temporal() {
  const [periodo, setPeriodo] = useState<PeriodoBi>(periodoInicial)
  const [metrica, setMetrica] = useState<Metrica>('receita_produto')
  const [aba, setAba] = useState<Aba>('hora')
  const [porHora, setPorHora] = useState<PontoHoraDTO[]>([])
  const [porDia, setPorDia] = useState<PontoDiaSemanaDTO[]>([])
  const [loading, setLoading] = useState(false)
  const [erro, setErro] = useState<string | null>(null)
  const cache = useBiCache()
  const { toast } = useToast()

  const cacheKey = `temporal_${metrica}`

  const buscar = useCallback(async (periodoOverride?: PeriodoBi, force = false, signal?: AbortSignal) => {
    const p = periodoOverride ?? periodo
    if (!force) {
      const cached = cache.get<{ hora: PontoHoraDTO[]; dia: PontoDiaSemanaDTO[] }>(cacheKey, p)
      if (cached) { setPorHora(cached.hora); setPorDia(cached.dia); return }
    }
    setErro(null)
    setLoading(true)
    try {
      const [hora, dia] = await Promise.all([
        fetchTemporalHora(p, metrica, signal),
        fetchTemporalDiaSemana(p, metrica, signal),
      ])
      setPorHora(hora)
      setPorDia(dia)
      cache.set(cacheKey, p, { hora, dia })
    } catch (e: unknown) {
      const err = e as { response?: { status?: number; data?: { detail?: string } }; name?: string }
      if (err?.name === 'CanceledError' || err?.name === 'AbortError') return
      if (err.response?.status === 400) setErro(err.response.data?.detail ?? 'Erro ao carregar dados.')
      else setErro('Erro ao carregar dados.')
    } finally {
      setLoading(false)
    }
  }, [periodo, metrica, cache]) // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    const controller = new AbortController()
    const signal = controller.signal
    const t = setTimeout(() => buscar(undefined, undefined, signal))
    return () => { clearTimeout(t); controller.abort() }
  }, [buscar])

  function handleBuscar(periodoOverride?: PeriodoBi) {
    cache.invalidate(cacheKey)
    buscar(periodoOverride, true)
  }

  const isReceita = metrica === 'receita_produto'
  const temDados = porHora.length > 0 || porDia.length > 0
  const dadosGrafico = aba === 'hora'
    ? porHora.map((d) => ({ label: `${d.hora}h`, valor: d.valor }))
    : porDia.map((d) => ({ label: d.dia_semana, valor: d.valor }))

  return (
    <BiPageLayout titulo="Distribuição Temporal" breadcrumb={[{ label: 'BI', path: '/bi' }, { label: 'Temporal' }]}>
      <Card variant="bordered">
        <div className="flex flex-col gap-4">
          <PeriodoForm value={periodo} onChange={setPeriodo} onBuscar={handleBuscar} loading={loading} presets={PRESETS_TEMPORAL} />
          <div className="flex flex-col gap-1">
            <label className="text-xs text-text-muted">Métrica</label>
            <select
              className="form-input-base w-40"
              value={metrica}
              onChange={(e) => setMetrica(e.target.value as Metrica)}
            >
              <option value="receita_produto">Receita</option>
              <option value="qtd_item">Quantidade</option>
            </select>
          </div>
          {erro && <ErrorBanner message={erro} />}
          <ExportButtons
            onExcel={() => { exportarExcelBI(periodo, 'diario', { metrica }); toast({ type: 'success', message: 'Excel exportado' }) }}
            onCsv={() => { baixarCSVdeArray(aba === 'hora' ? porHora : porDia, `temporal-${aba}`); toast({ type: 'success', message: 'CSV exportado' }) }}
            disabled={!temDados}
          />
        </div>
      </Card>

      {loading && !temDados && (
        <Card variant="bordered">
          <Skeleton className="h-5 w-40 mb-4" />
          <Skeleton variant="chart" />
        </Card>
      )}
      {!loading && !temDados && (
        <EmptyState title="Nenhum dado no período" description="Tente ampliar o período ou alterar os filtros." />
      )}
      {temDados && (
        <>
          <div className="flex gap-1 bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700/50 shadow-sm p-1 w-fit">
            {([['hora', 'Por Hora'], ['dia_semana', 'Por Dia da Semana']] as [Aba, string][]).map(([a, label]) => (
              <button
                key={a}
                onClick={() => setAba(a)}
                className={`px-5 py-2 rounded-xl text-sm font-semibold transition relative ${
                  aba === a ? 'bg-primary text-white' : 'text-text-muted hover:text-text-primary'
                }`}
              >
                {label}
              </button>
            ))}
          </div>

          <Card variant="bordered">
            <div className="flex items-center gap-2 mb-4">
              <Clock size={16} className="text-primary" />
              <h2 className="text-sm font-semibold text-text-primary">
                {aba === 'hora' ? 'Por Hora' : 'Por Dia da Semana'}
              </h2>
            </div>
            <div className="w-full aspect-[16/9] md:aspect-[21/9]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={dadosGrafico} margin={{ top: 0, right: 8, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="barGradientTemporal" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0%" stopColor={isReceita ? CHART.green : CHART.amber} stopOpacity={0.9} />
                    <stop offset="100%" stopColor={isReceita ? CHART.green : CHART.amber} stopOpacity={0.25} />
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e5e7eb" />
                <XAxis dataKey="label" tick={{ fontSize: 11, fill: 'var(--color-text-muted)' }} axisLine={{ stroke: 'var(--color-border)' }} tickLine={false} />
<YAxis
  tick={{ fontSize: 11, fill: 'var(--color-text-muted)' }}
  tickFormatter={(v) => isReceita ? `R$ ${(v / 1000).toFixed(0)}k` : `${(v / 1000).toFixed(0)}k un.`}
  axisLine={false}
  tickLine={false}
  width={40}
/>
                <Tooltip content={<BiTooltip />} cursor={{ fill: 'rgba(100,100,100,0.06)' }} />
                <Bar dataKey="valor" fill="url(#barGradientTemporal)" radius={[4, 4, 0, 0]} animationBegin={0} animationDuration={600} />
              </BarChart>
            </ResponsiveContainer>
            </div>
          </Card>
        </>
      )}
    </BiPageLayout>
  )
}

import { useState, useCallback, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import { subDays, format } from 'date-fns'
import PeriodoForm, { type Preset } from '../../components/bi/PeriodoForm'
import BiPageLayout from '../../components/bi/BiPageLayout'
import ExportButtons from '../../components/bi/ExportButtons'
import EmptyState from '../../components/ui/EmptyState'
import ErrorBanner from '../../components/ui/ErrorBanner'
import Card from '../../components/ui/Card'
import SectionHeader from '../../components/ui/SectionHeader'
import DataTable from '../../components/ui/DataTable'
import KpiCard from '../../components/bi/KpiCard'
import { fetchTrocas, exportarExcelBI } from '../../api/bi'
import { baixarCSVdeArray } from '../../utils/csv'
import type { TrocasDTO, PeriodoBi } from '../../types'
import { formatCurrency, formatNumber } from '../../utils/formatters'
import { useBiCache } from '../../stores/biCache'
import { useToast } from '../../hooks/useToast'
import { useCountUp } from '../../hooks/useCountUp'
import Skeleton from '../../components/ui/Skeleton'

const PRESETS_TROCAS: Preset[] = [
  { label: '7 dias', kind: 'days', days: 7 },
  { label: '30 dias', kind: 'days', days: 30 },
  { label: 'Este mês', kind: 'current_month' },
]

function periodoInicial(): PeriodoBi {
  return {
    data_inicio: format(subDays(new Date(), 30), 'yyyy-MM-dd'),
    data_fim: format(new Date(), 'yyyy-MM-dd'),
  }
}

export default function Trocas() {
  const navigate = useNavigate()
  const [periodo, setPeriodo] = useState<PeriodoBi>(periodoInicial)
  const [dados, setDados] = useState<TrocasDTO | null>(null)
  const [loading, setLoading] = useState(false)
  const [erro, setErro] = useState<string | null>(null)
  const cache = useBiCache()
  const { toast } = useToast()

  const animTrocas = useCountUp(dados?.total_trocas ?? 0, 600, !!dados)
  const animTaxa = useCountUp(dados?.taxa_troca_pct ?? 0, 600, !!dados)

  const buscar = useCallback(async (periodoOverride?: PeriodoBi, force = false, signal?: AbortSignal) => {
    const p = periodoOverride ?? periodo
    if (!force) {
      const cached = cache.get<TrocasDTO>('trocas', p)
      if (cached) { setDados(cached); return }
    }
    setErro(null)
    setLoading(true)
    try {
      const data = await fetchTrocas(p, signal)
      setDados(data)
      cache.set('trocas', p, data)
    } catch (e: unknown) {
      const err = e as { response?: { status?: number; data?: { detail?: string } }; name?: string }
      if (err?.name === 'CanceledError' || err?.name === 'AbortError') return
      if (err.response?.status === 400) setErro(err.response.data?.detail ?? 'Erro ao carregar dados.')
      else setErro('Erro ao carregar dados.')
    } finally {
      setLoading(false)
    }
  }, [periodo, cache])

  useEffect(() => {
    const controller = new AbortController()
    const signal = controller.signal
    const t = setTimeout(() => buscar(undefined, undefined, signal))
    return () => { clearTimeout(t); controller.abort() }
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  function handleBuscar(periodoOverride?: PeriodoBi) {
    cache.invalidate('trocas')
    buscar(periodoOverride, true)
  }

  return (
    <BiPageLayout titulo="Trocas" breadcrumb={[{ label: 'BI', path: '/bi' }, { label: 'Trocas' }]}>
      {/* Filters */}
      <Card variant="bordered">
        <PeriodoForm value={periodo} onChange={setPeriodo} onBuscar={handleBuscar} loading={loading} presets={PRESETS_TROCAS} />
        {erro && <div className="mt-3"><ErrorBanner message={erro} /></div>}
        <div className="mt-3">
          <ExportButtons
            onExcel={() => { exportarExcelBI(periodo, 'trocas'); toast({ type: 'success', message: 'Excel exportado' }) }}
            onCsv={() => { if (dados) { baixarCSVdeArray(dados.por_produto, 'trocas'); toast({ type: 'success', message: 'CSV exportado' }) } }}
            disabled={!dados}
          />
        </div>
      </Card>

      {/* Loading skeleton */}
      {loading && !dados && (
        <>
          <div className="grid grid-cols-2 gap-3">
            <Skeleton variant="kpi" />
            <Skeleton variant="kpi" />
          </div>
          <Card variant="bordered">
            <Skeleton className="h-5 w-40 mb-4" />
            {Array.from({ length: 5 }).map((_, i) => (
              <Skeleton key={i} variant="table-row" className="mb-2" />
            ))}
          </Card>
        </>
      )}

      {/* Empty state */}
      {!loading && !dados && !erro && (
        <EmptyState title="Nenhum dado no período" description="Tente ampliar o período." />
      )}

      {/* Data */}
      {dados && (
        <>
          <div className="grid grid-cols-2 gap-3">
            <KpiCard label="Total de Trocas" valor={formatNumber(animTrocas)} />
            <KpiCard label="Taxa de Troca" valor={`${animTaxa.toFixed(2)}%`} />
          </div>

          <Card variant="bordered">
            <SectionHeader>
              Por produto <span className="text-text-muted font-normal">({dados.por_produto.length})</span>
            </SectionHeader>
            {dados.por_produto.length === 0 ? (
              <p className="text-sm text-text-muted">Nenhuma troca no período.</p>
            ) : (
              <DataTable
                data={dados.por_produto}
                columns={[
                  { key: 'codigo', label: 'Código', mono: true, render: (item) => <span className="truncate block font-mono text-text-muted" title={item.codigo}>{item.codigo}</span> },
                  { key: 'produto', label: 'Produto', render: (item) => <span className="truncate block" title={item.produto}>{item.produto}</span> },
                  { key: 'receita', label: 'Valor', align: 'right', mono: true, render: (item) => <span className="font-semibold">{formatCurrency(item.receita)}</span> },
                ]}
                rowKey={(item) => item.codigo}
                onRowClick={(item) => navigate(`/bi/sku?codigo=${item.codigo}`)}
                density="sm"
              />
            )}
          </Card>
        </>
      )}
    </BiPageLayout>
  )
}

import { useState, useEffect, useRef } from 'react'
import { Camera, Loader2, Search as SearchIcon, BarChart3 } from 'lucide-react'
import { useNavigate } from 'react-router-dom'
import { formatCurrency } from '../utils/formatters'
import { buscarProduto, buscarProdutosPorNome, registrarNaoEncontrado } from '../api/produtos'
import type { ProdutoBasico, ProdutoCompleto } from '../types'
import { useAuth } from '../hooks/useAuth'
import LeitorCodigo from '../components/LeitorCodigo'
import PageContainer from '../components/layout/PageContainer'
import Card from '../components/ui/Card'
import Button from '../components/ui/Button'
import Badge from '../components/ui/Badge'
import Modal from '../components/ui/Modal'
import EmptyState from '../components/ui/EmptyState'

  function isCompleto(p: ProdutoBasico | ProdutoCompleto): p is ProdutoCompleto {
  return 'preco_custo' in p
}

export default function Busca() {
  const navigate = useNavigate()
  const { getRole } = useAuth()

  const [codigo, setCodigo] = useState('')
  const [produto, setProduto] = useState<ProdutoBasico | ProdutoCompleto | null>(null)
  const [erro, setErro] = useState('')
  const [loading, setLoading] = useState(false)
  const [cameras, setCameras] = useState(false)
  const [codigoNaoEncontrado, setCodigoNaoEncontrado] = useState<string | null>(null)
  const [observacao, setObservacao] = useState('')
  const [enviandoObs, setEnviandoObs] = useState(false)
  const [searchQuery, setSearchQuery] = useState('')
  const [searchResults, setSearchResults] = useState<ProdutoBasico[]>([])
  const [searching, setSearching] = useState(false)
  const searchTimer = useRef<ReturnType<typeof setTimeout> | null>(null)
  const mountedRef = useRef(true)

  useEffect(() => {
    mountedRef.current = true
    return () => { mountedRef.current = false }
  }, [])

  useEffect(() => {
    if (searchTimer.current) clearTimeout(searchTimer.current)
    const q = searchQuery.trim()
    searchTimer.current = setTimeout(async () => {
      if (!mountedRef.current) return
      if (q.length < 2) { setSearchResults([]); setSearching(false); return }
      setSearching(true)
      try {
        const results = await buscarProdutosPorNome(q)
        if (mountedRef.current) setSearchResults(results)
      } catch {
        if (mountedRef.current) setSearchResults([])
      } finally {
        if (mountedRef.current) setSearching(false)
      }
    }, 300)
    return () => { if (searchTimer.current) clearTimeout(searchTimer.current) }
  }, [searchQuery])

  const role = getRole()

  async function handleBuscar(codigoParam?: string) {
    const valor = (codigoParam ?? codigo).trim()
    if (!valor) return
    setErro('')
    setProduto(null)
    setLoading(true)
    try {
      const produtoEncontrado = await buscarProduto(valor)
      if (!mountedRef.current) return
      setProduto(produtoEncontrado)
    } catch (e: unknown) {
      const error = e as { response?: { status?: number } }
      if (error.response?.status === 404) setCodigoNaoEncontrado(valor)
      else if (error.response?.status === 400) setErro('Código inválido.')
      else setErro('Erro ao consultar. Tente novamente.')
    } finally {
      setLoading(false)
    }
  }

  function handleLeitura(codigoLido: string) {
    setCameras(false)
    setCodigo(codigoLido)
    handleBuscar(codigoLido)
  }

  async function handleEnviarObservacao() {
    if (!codigoNaoEncontrado) return
    setEnviandoObs(true)
    try { await registrarNaoEncontrado(codigoNaoEncontrado, observacao.trim()) }
    finally { setCodigoNaoEncontrado(null); setObservacao(''); setEnviandoObs(false) }
  }

  return (
    <PageContainer maxWidth="full">
      <div className="flex flex-col items-center px-4 py-4">
      {cameras && (
        <LeitorCodigo onLeitura={handleLeitura} onFechar={() => setCameras(false)} />
      )}

      {/* Modal Produto não encontrado */}
      <Modal
        open={!!codigoNaoEncontrado}
        onClose={() => { setCodigoNaoEncontrado(null); setObservacao('') }}
        title="Produto não encontrado"
        actions={
          <>
            <Button variant="ghost" onClick={() => { setCodigoNaoEncontrado(null); setObservacao('') }}>
              Ignorar
            </Button>
            <Button onClick={handleEnviarObservacao} loading={enviandoObs} disabled={!observacao.trim()}>
              Registrar
            </Button>
          </>
        }
      >
        <p className="text-xs text-text-muted mb-3">Código: {codigoNaoEncontrado}</p>
        <textarea
          className="form-input-base resize-none"
          placeholder="Observação (ex: Coca Cola lata 250ml)"
          rows={3}
          value={observacao}
          onChange={(e) => setObservacao(e.target.value)}
          autoFocus
        />
      </Modal>

      {/* Input de busca EAN/PLU */}
      <div className="w-full max-w-md flex gap-2 mb-6">
        <input
          aria-label="Código EAN ou PLU"
          className="form-input-base flex-1 rounded-xl"
          placeholder="Digite o código EAN ou PLU"
          value={codigo}
          onChange={(e) => setCodigo(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && handleBuscar()}
          autoFocus
        />
        <button
          onClick={() => setCameras(true)}
          className="md:hidden bg-bg-input border border-border-input hover:bg-bg-hover text-text-secondary px-3 py-2 rounded-xl transition"
          aria-label="Ler código de barras"
        >
          <Camera size={18} />
        </button>
        <Button onClick={() => handleBuscar()} loading={loading}>
          <SearchIcon size={14} /> Buscar
        </Button>
      </div>

      {/* Busca por nome */}
      <div className="w-full max-w-md mb-6 relative">
        <div className="relative">
          <input
            aria-label="Buscar produto por nome"
            className="form-input-base rounded-xl pr-10"
            placeholder="Buscar produto por nome..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
          {searching && (
            <span className="absolute right-3 top-1/2 -translate-y-1/2">
              <Loader2 size={14} className="animate-spin text-text-muted" />
            </span>
          )}
        </div>
        {searchResults.length > 0 && (
          <div className="mt-2 bg-bg-card rounded-xl shadow-modal border border-border divide-y divide-border overflow-y-auto max-h-60 absolute left-0 right-0 z-20">
            {searchResults.map((p) => (
              <button
                key={p.codigo_chamada}
                onClick={() => {
                  setCodigo(p.codigo_chamada)
                  handleBuscar(p.codigo_chamada)
                  setSearchQuery('')
                  setSearchResults([])
                }}
                className="w-full text-left px-4 py-3 hover:bg-primary-lighter transition flex justify-between items-center"
              >
                <span className="text-sm font-medium text-text-primary">{p.nome}</span>
                <span className="text-xs text-text-muted">{p.codigo_chamada}</span>
              </button>
            ))}
          </div>
        )}
        {searchQuery.trim().length >= 2 && !searching && searchResults.length === 0 && (
          <EmptyState title="Nenhum produto encontrado" description={`Nenhum resultado para "${searchQuery}"`} />
        )}
      </div>

      {erro && <p className="text-danger text-sm mb-4" role="alert">{erro}</p>}

      {produto && (
        <>
        <Card variant="elevated" padding="md" className="w-full max-w-md">
          <div>
            <p className="text-xs text-text-muted uppercase tracking-wider font-medium">Produto</p>
            <p className="text-base md:text-lg font-bold text-text-primary break-words">{produto.nome}</p>
          </div>

          <div className="flex gap-3 mt-3 flex-wrap">
            <Badge variant="info">{produto.grupo}</Badge>
            <Badge variant="default">{produto.familia}</Badge>
          </div>

          <div className="border-t border-border pt-3 mt-3">
            <p className="text-xs text-text-muted uppercase tracking-wider font-medium">Preço de Venda</p>
            <p className="text-xl md:text-3xl font-bold text-primary break-words animate-pulse-glow">
              {formatCurrency(produto.preco_venda)}
            </p>
          </div>

          <div className="border-t border-border pt-3 mt-3">
            <p className="text-xs text-text-muted uppercase tracking-wider font-medium">Estoque</p>
            <p className="text-sm font-semibold text-text-primary">{produto.estoque} un.</p>
          </div>

          {isCompleto(produto) && (
            <>
              <div className="flex gap-4 border-t border-border pt-3 mt-3">
                <div>
                  <p className="text-xs text-text-muted uppercase tracking-wider font-medium">Preço de Custo</p>
                  <p className="text-sm font-semibold text-text-primary">
                    {formatCurrency(produto.preco_custo)}
                  </p>
                </div>
              </div>
              <div className="flex gap-4 mt-2">
                <div>
                  <p className="text-xs text-text-muted uppercase tracking-wider font-medium">Markup</p>
                  <p className="text-sm font-semibold text-text-primary">
                    {(produto.markup * 100).toFixed(2)}%
                  </p>
                </div>
                <div>
                  <p className="text-xs text-text-muted uppercase tracking-wider font-medium">Margem</p>
                  <p className="text-sm font-semibold text-text-primary">
                    {(produto.margem * 100).toFixed(2)}%
                  </p>
                </div>
              </div>
            </>
          )}
        </Card>

        {(role === 'supervisor' || role === 'admin') && (
          <button
            onClick={() => navigate(`/bi/sku?codigo=${produto.codigo_chamada ?? ''}&force=1`)}
            className="inline-flex items-center gap-2 px-4 py-2.5 bg-primary text-white text-sm font-medium rounded-lg hover:bg-primary-hover transition-colors mt-4 w-full max-w-md"
          >
            <BarChart3 size={16} />
            Análise de Vendas
          </button>
        )}
      </>
      )}

      {!loading && !produto && !searchQuery.trim() && !erro && (
        <EmptyState
          title="Busque um produto"
          description="Digite o código EAN/PLU, use a câmera ou busque por nome"
        />
      )}
      </div>
    </PageContainer>
  )
}

import { useState, useEffect } from 'react'
import { Check, Loader2, Store, Database, MessageSquare, Mail, Brain } from 'lucide-react'
import Card from '../components/ui/Card'
import PageContainer from '../components/layout/PageContainer'
import ConfigGeral from '../components/config/ConfigGeral'
import ConfigErp from '../components/config/ConfigErp'
import ConfigWhatsApp from '../components/config/ConfigWhatsApp'
import ConfigEmail from '../components/config/ConfigEmail'
import ConfigIntelligence from '../components/config/ConfigIntelligence'
import { getConfiguracoes, atualizarConfiguracoes, uploadLogo } from '../api/admin'
import { invalidateConfigCache } from '../stores/configStore'
import { useToast } from '../hooks/useToast'
import type { ConfigForm } from '../components/config/types'

const TABS = [
  { id: 'geral', label: 'Geral', icon: Store },
  { id: 'erp', label: 'ERP / Sync', icon: Database },
  { id: 'whatsapp', label: 'WhatsApp', icon: MessageSquare },
  { id: 'email', label: 'E-mail', icon: Mail },
  { id: 'intelligence', label: 'Intelligence', icon: Brain },
]

export default function Configuracoes() {
  const { toast } = useToast()
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [saved, setSaved] = useState(false)
  const [activeTab, setActiveTab] = useState('geral')
  const [form, setForm] = useState<ConfigForm>({})
  const [logoPreview, setLogoPreview] = useState<string | null>(null)

  useEffect(() => {
    getConfiguracoes()
      .then((c) => {
        setForm(c.configuracoes)
        if (c.configuracoes.logo_url) setLogoPreview(c.configuracoes.logo_url)
      })
      .catch(() => toast({ type: 'error', message: 'Erro ao carregar configurações' }))
      .finally(() => setLoading(false))
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  async function handleSalvar() {
    setSaving(true)
    setSaved(false)
    try {
      const resp = await atualizarConfiguracoes(form as Record<string, string>)
      invalidateConfigCache()
      if (resp.configuracoes.logo_url) setLogoPreview(resp.configuracoes.logo_url)
      setSaved(true)
      toast({ type: 'success', message: 'Configurações salvas' })
      setTimeout(() => setSaved(false), 2000)
    } catch {
      toast({ type: 'error', message: 'Erro ao salvar configurações' })
    } finally {
      setSaving(false)
    }
  }

  async function handleLogoUpload(file: File) {
    const allowedTypes = ['image/png', 'image/jpeg', 'image/webp', 'image/svg+xml']
    if (!allowedTypes.includes(file.type)) {
      toast({ type: 'error', message: 'Formato inválido. Use PNG, JPG, WebP ou SVG.' })
      return
    }
    if (file.size > 2 * 1024 * 1024) {
      toast({ type: 'error', message: 'Arquivo muito grande. Máximo: 2MB.' })
      return
    }
    try {
      const result = await uploadLogo(file)
      invalidateConfigCache()
      setLogoPreview(result.logo_url)
      setForm((prev) => ({ ...prev, logo_url: result.logo_url }))
      toast({ type: 'success', message: 'Logo atualizada' })
    } catch {
      toast({ type: 'error', message: 'Erro ao fazer upload da logo' })
    }
  }

  function updateField(key: string, value: string) {
    setForm((prev) => ({ ...prev, [key]: value }))
  }

  if (loading) {
    return (
      <PageContainer maxWidth="md">
        <div className="flex items-center justify-center gap-2 text-sm text-text-muted mt-12">
          <Loader2 size={16} className="animate-spin" /> Carregando...
        </div>
      </PageContainer>
    )
  }

  return (
    <PageContainer maxWidth="md">
      <div className="flex flex-col gap-4">
        {/* Tab bar */}
        <Card variant="default" className="p-1">
          <div className="flex gap-0.5 overflow-x-auto lg:justify-evenly">
            {TABS.map(({ id, label, icon: Icon }) => (
              <button
                key={id}
                onClick={() => setActiveTab(id)}
                className={`flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-xs font-semibold transition whitespace-nowrap shrink-0 lg:flex-1 lg:justify-center ${
                  activeTab === id
                    ? 'bg-primary text-white shadow-sm'
                    : 'text-text-muted hover:bg-bg-hover hover:text-text-primary'
                }`}
              >
                <Icon size={13} />
                <span className="hidden sm:inline">{label}</span>
              </button>
            ))}
          </div>
        </Card>

        {/* Tab content */}
        <Card variant="default" padding="none">
          {activeTab === 'geral' && (
            <ConfigGeral form={form} updateField={updateField} logoPreview={logoPreview} handleLogoUpload={handleLogoUpload} />
          )}
          {activeTab === 'erp' && <ConfigErp form={form} updateField={updateField} />}
          {activeTab === 'whatsapp' && <ConfigWhatsApp form={form} updateField={updateField} />}
          {activeTab === 'email' && <ConfigEmail form={form} updateField={updateField} />}
          {activeTab === 'intelligence' && <ConfigIntelligence form={form} updateField={updateField} />}
        </Card>

        {/* Save bar */}
        <div className="flex items-center justify-center gap-3 py-2">
          <button
            onClick={handleSalvar}
            disabled={saving}
            className={`inline-flex items-center gap-2 font-semibold px-8 py-2.5 rounded-xl transition disabled:opacity-50 text-sm ${
              saved
                ? 'bg-emerald-500 text-white'
                : 'bg-primary hover:bg-primary-hover text-white shadow-sm hover:shadow'
            }`}
          >
            {saved ? <Check size={15} /> : null}
            {saving ? 'Salvando...' : saved ? 'Salvo!' : 'Salvar configurações'}
          </button>
        </div>
      </div>
    </PageContainer>
  )
}

import { useState, useRef } from 'react'
import { buscarProduto } from '../api/produtos'
import LeitorCodigo from '../components/LeitorCodigo'
import { gerarCSV, baixarCSV, type CsvRow } from '../utils/csv'
import { Camera, Tag, Trash2, Download, Plus } from 'lucide-react'
import { useLocalStorage } from '../hooks/useLocalStorage'
import PageContainer from '../components/layout/PageContainer'
import Card from '../components/ui/Card'
import Badge from '../components/ui/Badge'
import Button from '../components/ui/Button'

interface ItemEtiqueta {
  codigo: string
  nome: string
}

export default function Etiquetas() {
  const [itens, setItens] = useLocalStorage<ItemEtiqueta[]>('etiquetas_lista', [])
  const [erro, setErro] = useState('')
  const [camera, setCamera] = useState(false)
  const inputRef = useRef<HTMLInputElement>(null)

  async function handleCodigo(codigo: string) {
    setErro('')
    const codigoLimpo = codigo.trim()
    if (!codigoLimpo) return

    if (itens.some(i => i.codigo === codigoLimpo)) {
      setErro(`Produto ${codigoLimpo} já está na lista.`)
      if (inputRef.current) inputRef.current.value = ''
      return
    }

    try {
      const produto = await buscarProduto(codigoLimpo)
      setItens(prev => [{ codigo: produto.codigo_chamada, nome: produto.nome }, ...prev].slice(0, 100))
      if (inputRef.current) inputRef.current.value = ''
    } catch (e: unknown) {
      const error = e as { response?: { status?: number } }
      if (error.response?.status === 404) setErro('Produto não encontrado.')
      else if (error.response?.status === 400) setErro('Código inválido.')
      else setErro('Erro ao consultar.')
    }
  }

  function handleKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
    if (e.key === 'Enter') {
      handleCodigo((e.target as HTMLInputElement).value)
    }
  }

  function remover(codigo: string) {
    setItens(prev => prev.filter(i => i.codigo !== codigo))
  }

  function handleExportar() {
    if (itens.length === 0) return
    const rows: CsvRow[] = itens.map(i => ({ codigo: i.codigo, tipo: 'chamada', quantidade: 1 }))
    baixarCSV(gerarCSV(rows), 'etiquetas')
  }

  return (
    <PageContainer maxWidth="md">
      {camera && (
        <LeitorCodigo
          onLeitura={(codigo) => { setCamera(false); setTimeout(() => handleCodigo(codigo), 50) }}
          onFechar={() => setCamera(false)}
        />
      )}

      <div className="w-full max-w-md mx-auto flex flex-col gap-5">

        {/* Input card */}
        <Card variant="elevated" padding="lg">
          <div className="flex items-center gap-3 mb-5">
            <div className="w-10 h-10 rounded-xl bg-primary-light flex items-center justify-center">
              <Tag size={20} className="text-primary" />
            </div>
            <div>
              <h2 className="text-base font-semibold text-text-primary">Bipar produtos</h2>
              <p className="text-xs text-text-muted">Adicione produtos à lista de etiquetas</p>
            </div>
          </div>
          <div className="flex gap-2 w-full">
            <input
              ref={inputRef}
              aria-label="Código do produto"
              className="form-input-base flex-1 min-w-0 w-full rounded-xl"
              placeholder="Digite ou bipe o código"
              onKeyDown={handleKeyDown}
              autoFocus
            />
            <button
              onClick={() => setCamera(true)}
              className="md:hidden bg-bg-input border border-border-input hover:bg-bg-hover text-text-secondary px-2 py-2 rounded-xl transition shrink-0"
              aria-label="Ler código de barras"
            >
              <Camera size={18} />
            </button>
          </div>
          {erro && <p className="text-danger text-sm mt-2" role="alert">{erro}</p>}
        </Card>

        {/* Lista card */}
        {itens.length > 0 && (
          <Card variant="elevated" padding="lg">
            <div className="flex justify-between items-center mb-4">
              <div className="flex items-center gap-2">
                <Plus size={16} className="text-text-muted" />
                <h2 className="text-base font-semibold text-text-primary">
                  Lista <span className="text-text-muted font-normal text-sm">({itens.length} produtos)</span>
                </h2>
              </div>
              <div className="flex gap-2">
                <Button variant="ghost" onClick={() => setItens([])}>
                  <Trash2 size={13} /> Limpar
                </Button>
                <Button onClick={handleExportar}>
                  <Download size={13} /> Exportar
                </Button>
              </div>
            </div>

            <div className="flex flex-col gap-1.5">
              {itens.map(item => (
                <div key={item.codigo} className="flex justify-between items-center border border-border rounded-xl px-4 py-3 hover:bg-bg-hover transition group">
                  <div className="flex items-center gap-3 min-w-0">
                    <div className="w-8 h-8 rounded-lg bg-bg-card flex items-center justify-center shrink-0">
                      <Tag size={14} className="text-text-muted" />
                    </div>
                    <div className="flex items-center gap-1 min-w-0 overflow-hidden">
                      <Badge variant="info" className="shrink-0">{item.codigo}</Badge>
                      <span className="text-sm text-text-secondary truncate min-w-0">{item.nome}</span>
                    </div>
                  </div>
                  <button
                    onClick={() => remover(item.codigo)}
                    className="text-text-muted hover:text-danger transition opacity-100 sm:opacity-0 sm:group-hover:opacity-100 p-1 shrink-0"
                    aria-label={`Remover ${item.nome}`}
                  >
                    <Trash2 size={14} />
                  </button>
                </div>
              ))}
            </div>
          </Card>
        )}
      </div>
    </PageContainer>
  )
}

import { useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import { useAuth } from '../hooks/useAuth'

/**
 * Home — redireciona para a página mais relevante baseada no perfil.
 *
 * admin      → /admin (Sync ETL)
 * supervisor → /bi (Dashboard Consolidado)
 * operador   → /inventario (Inventário)
 *
 * Se não houver role (não autenticado), o AppLayout já cuida do redirect
 * para /login via ProtectedRoute.
 */
export default function Home() {
  const navigate = useNavigate()
  const { getRole } = useAuth()
  const role = getRole()

  useEffect(() => {
    if (role === 'admin') navigate('/admin', { replace: true })
    else if (role === 'supervisor') navigate('/bi', { replace: true })
    else navigate('/inventario', { replace: true })
  }, [role, navigate])

  return null
}

// src/pages/Inventario.tsx  — substitui o arquivo existente na íntegra
//
// Mudanças em relação ao original:
//   • handleExportarExcel / handleConsolidadoExcel → chamam exportarExcelSessao /
//     exportarExcelConsolidado do backend (remove dependência de 'xlsx' aqui)
//   • Remove import de 'xlsx' (não é mais necessário nesta página)
//   • Botões de Excel agora mostram loading enquanto o backend gera o arquivo
//   • Todo o restante permanece idêntico

import { useState, useRef, useEffect, useCallback } from 'react'
import { Camera, Plus, Minus, Download, Trash2, LogOut, Check, FileSpreadsheet } from 'lucide-react'
import { buscarProduto } from '../api/produtos'
import LeitorCodigo from '../components/LeitorCodigo'
import { useAuth } from '../hooks/useAuth'
import { useToast } from '../hooks/useToast'
import Button from '../components/ui/Button'
import Modal from '../components/ui/Modal'
import Skeleton from '../components/ui/Skeleton'
import Card from '../components/ui/Card'
import {
  getSessoesInventario,
  criarSessaoInventario,
  entrarSessaoInventario,
  encerrarSessaoInventario,
  getItensInventario,
  adicionarItemInventario,
  atualizarItemInventario,
  limparItensInventario,
  getConsolidadoGeral,
  exportarExcelSessao,
  exportarExcelConsolidado,
} from '../api/admin'
import type { SessaoInventario, ItemInventario } from '../types/inventario'

export default function Inventario() {
  const { getRole } = useAuth()
  const role = getRole()
  const isSupervisor = role === 'supervisor' || role === 'admin'

  const [sessoes, setSessoes] = useState<SessaoInventario[]>([])
  const [sessaoAtiva, setSessaoAtiva] = useState<SessaoInventario | null>(null)
  const [itens, setItens] = useState<ItemInventario[]>([])

  const [erro, setErro] = useState('')
  const [camera, setCamera] = useState(false)
  const [loadingSessoes, setLoadingSessoes] = useState(true)
  const [editando, setEditando] = useState<Record<string, string>>({})
  const [novaSessaoModal, setNovaSessaoModal] = useState(false)
  const [novaSessaoNome, setNovaSessaoNome] = useState('')
  const [criandoSessao, setCriandoSessao] = useState(false)
  const [confirmarEncerrar, setConfirmarEncerrar] = useState(false)
  const [confirmarLimpar, setConfirmarLimpar] = useState(false)
  const [editSheetItem, setEditSheetItem] = useState<ItemInventario | null>(null)
  const [scanFeedback, setScanFeedback] = useState<string | null>(null)
  const [highlightedCode, setHighlightedCode] = useState<string | null>(null)
  const highlightTimer = useRef<ReturnType<typeof setTimeout> | null>(null)
  const [excelLoading, setExcelLoading] = useState(false)
  const [excelConsolidadoLoading, setExcelConsolidadoLoading] = useState(false)

  // Modal "produto não encontrado" — permite adicionar com observação
  const [naoCadastradoModal, setNaoCadastradoModal] = useState<{ codigo: string } | null>(null)
  const [naoCadastradoObs, setNaoCadastradoObs] = useState('')

  const processando = useRef<Set<string>>(new Set())
  const ultimaLeitura = useRef<Map<string, number>>(new Map())
  const ultimaQualquerLeitura = useRef(0)
  const pausaEscaneio = useRef(false)
  const inputRef = useRef<HTMLInputElement>(null)
  const conviteRef = useRef<HTMLInputElement>(null)
  const scrollPosRef = useRef(0)
  const feedbackTimer = useRef<ReturnType<typeof setTimeout> | null>(null)
  const sessaoAtivaRef = useRef<number | null>(null)

  const { toast } = useToast()

  // Consolidado de todas as sessões (auto-refreshed, supervisor only)
  const [consolidadoItems, setConsolidadoItems] = useState<ItemInventario[]>([])
  const [consolidadoLoading, setConsolidadoLoading] = useState(false)

  const fetchConsolidado = useCallback(async () => {
    if (!isSupervisor) return
    setConsolidadoLoading(true)
    try {
      const items = await getConsolidadoGeral()
      setConsolidadoItems(items)
    } catch (err) {
      console.error('Erro ao carregar consolidado:', err)
    } finally { setConsolidadoLoading(false) }
  }, [isSupervisor])

  useEffect(() => {
    if (sessaoAtiva && isSupervisor) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      fetchConsolidado()
    }
  }, [sessaoAtiva, isSupervisor, fetchConsolidado])

  useEffect(() => {
    // Reset pausaEscaneio ao montar para evitar bloqueio de scans se
    // o modal "não cadastrado" estava aberto quando o componente desmontou
    pausaEscaneio.current = false
    getSessoesInventario()
      .then(setSessoes)
      .catch(() => setErro('Erro ao carregar sessões'))
      .finally(() => setLoadingSessoes(false))
  }, [])

  useEffect(() => {
    if (!sessaoAtiva) return
    getItensInventario(sessaoAtiva.id, false)
      .then(setItens)
      .catch(() => setErro('Erro ao carregar itens'))
  }, [sessaoAtiva])

  // Mantém sessaoAtivaRef sincronizado com sessaoAtiva
  useEffect(() => {
    sessaoAtivaRef.current = sessaoAtiva?.id ?? null
  }, [sessaoAtiva])

  useEffect(() => {
    if (!sessaoAtiva || scrollPosRef.current <= 0) return
    requestAnimationFrame(() => {
      window.scrollTo({ top: scrollPosRef.current, behavior: 'auto' })
      scrollPosRef.current = 0
    })
  }, [sessaoAtiva])

  function mostrarFeedback(nome: string) {
    setScanFeedback(null)
    if (feedbackTimer.current) clearTimeout(feedbackTimer.current)
    requestAnimationFrame(() => {
      setScanFeedback(nome)
      feedbackTimer.current = setTimeout(() => setScanFeedback(null), 700)
    })
  }

  function haptico() {
    try { navigator.vibrate?.(20) } catch { /* vibrate not supported */ }
  }

  function handleVoltar() {
    scrollPosRef.current = window.scrollY
    setSessaoAtiva(null)
    setItens([])
    setEditando({})
    setCamera(false)
    getSessoesInventario().then(setSessoes).catch(() => {})
  }

  // ─── Produto não cadastrado — adicionar com observação ────────────────────
  async function handleAdicionarNaoCadastrado() {
    if (!sessaoAtiva || !naoCadastradoModal) return
    const codigo = naoCadastradoModal.codigo
    pausaEscaneio.current = false
    ultimaQualquerLeitura.current = Date.now() - 500  // 500ms de folga p/ frames residuais
    setNaoCadastradoModal(null)

    try {
      const obs = naoCadastradoObs.trim()
      setItens(prev => [{
        codigo,
        nome: 'Não cadastrado',
        grupo: '',
        familia: '',
        quantidade: 1,
        observacao: obs || undefined,
      }, ...prev].slice(0, 100))
      await adicionarItemInventario(sessaoAtiva.id, {
        codigo,
        nome: 'Não cadastrado',
        grupo: '',
        familia: '',
        observacao: obs,
      })
      if (inputRef.current) inputRef.current.value = ''
      haptico()
      mostrarFeedback('Adicionado sem cadastro')
      fetchConsolidado()
    } catch {
      setErro('Erro ao adicionar produto')
    }
  }

  // ─── TXT consolidado (padrão coletador Alterdata) ─────────────────────────
  // Formato: <codigo_interno>;<quantidade>  — uma linha por produto, sem cabeçalho.
  // BOM UTF-8 incluído para compatibilidade com Windows/Alterdata Import.
  // Este é o formato nativo do coletador Alterdata (não é acoplamento):
  // o Alterdata ERP importa diretamente via menu Estoque > Inventário > Importar Coletora,
  // esperando exatamente este layout de campos separados por ponto-e-vírgula.
  async function handleConsolidadoTxt() {
    setErro('')
    try {
      const items = await getConsolidadoGeral()
      if (items.length === 0) { setErro('Nenhum item encontrado nas sessões.'); return }
      const linhas = items.map(i => `${i.codigo};${i.quantidade}`).join('\n')
      const bom = '\uFEFF'
      const blob = new Blob([bom + linhas], { type: 'text/plain;charset=utf-8;' })
      const url = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = url
      link.download = `consolidado_geral_${new Date().toISOString().slice(0, 10)}.txt`
      link.click()
      URL.revokeObjectURL(url)
      toast({ type: 'success', message: 'TXT consolidado baixado!' })
    } catch {
      setErro('Erro ao gerar relatório consolidado')
    }
  }

  // ─── Excel consolidado (via backend — inclui aba Delta) ───────────────────
  async function handleConsolidadoExcel() {
    setExcelConsolidadoLoading(true)
    setErro('')
    try {
      await exportarExcelConsolidado()
      toast({ type: 'success', message: 'Excel consolidado baixado!' })
    } catch {
      setErro('Erro ao gerar Excel consolidado')
    } finally {
      setExcelConsolidadoLoading(false)
    }
  }

  async function handleCriarSessao() {
    if (!novaSessaoNome.trim()) return
    setCriandoSessao(true)
    try {
      const s = await criarSessaoInventario(novaSessaoNome.trim())
      setSessoes(prev => [s, ...prev])
      setSessaoAtiva(s)
      setNovaSessaoModal(false)
      setNovaSessaoNome('')
    } catch {
      setErro('Erro ao criar sessão')
    } finally {
      setCriandoSessao(false)
    }
  }

  async function handleEntrarSessao() {
    const codigo = conviteRef.current?.value?.trim().toUpperCase()
    if (!codigo) return
    try {
      const s = await entrarSessaoInventario(codigo)
      setSessaoAtiva(s)
    } catch {
      setErro('Sessão não encontrada')
    }
  }

  async function handleEncerrarSessao() {
    if (!sessaoAtiva) return
    try {
      await encerrarSessaoInventario(sessaoAtiva.id)
      setConfirmarEncerrar(false)
      handleVoltar()
    } catch {
      setErro('Erro ao encerrar sessão')
    }
  }

  async function handleCodigo(codigo: string) {
    if (!sessaoAtiva) return
    if (pausaEscaneio.current) return  // modal "não cadastrado" aberto

    const agora = Date.now()

    // Debounce global de 2s — QUALQUER leitura, independente do código ou fonte
    if (agora - ultimaQualquerLeitura.current < 2000) return
    ultimaQualquerLeitura.current = agora

    setErro('')
    const codigoLimpo = codigo.trim()
    if (!codigoLimpo) return

    // Cooldown de 1.5s por código específico (câmera 30fps)
    const ultima = ultimaLeitura.current.get(codigoLimpo) ?? 0
    if (agora - ultima < 1500) return
    ultimaLeitura.current.set(codigoLimpo, agora)

    if (processando.current.has(codigoLimpo)) return
    processando.current.add(codigoLimpo)

    try {
      const existente = itens.find(i => i.codigo === codigoLimpo)
      if (existente) {
        // Move to top + increment + highlight
        setItens(prev => {
          const semItem = prev.filter(i => i.codigo !== codigoLimpo)
          return [{ ...existente, quantidade: existente.quantidade + 1 }, ...semItem]
        })
        if (highlightTimer.current) clearTimeout(highlightTimer.current)
        setHighlightedCode(codigoLimpo)
        highlightTimer.current = setTimeout(() => setHighlightedCode(null), 1500)
        await adicionarItemInventario(sessaoAtiva.id, { codigo: codigoLimpo, nome: existente.nome, grupo: existente.grupo, familia: existente.familia })
        if (inputRef.current) inputRef.current.value = ''
        haptico()
        mostrarFeedback(existente.nome)
        return
      }

      const produto = await buscarProduto(codigoLimpo)
      // Guard: sessão pode ter mudado durante o await — verifica stale closure
      if (!sessaoAtivaRef.current || sessaoAtivaRef.current !== sessaoAtiva?.id) return
      const internalCode = produto.codigo_chamada

      setItens(prev => {
        const jaExiste = prev.find(i => i.codigo === internalCode)
        if (jaExiste) {
          // Move to top + increment + highlight
          if (highlightTimer.current) clearTimeout(highlightTimer.current)
          setHighlightedCode(internalCode)
          highlightTimer.current = setTimeout(() => setHighlightedCode(null), 1500)
          const semItem = prev.filter(i => i.codigo !== internalCode)
          return [{ ...jaExiste, quantidade: jaExiste.quantidade + 1 }, ...semItem]
        }
        // Novo item: prepend ao topo
        return [{ codigo: internalCode, nome: produto.nome, grupo: produto.grupo, familia: produto.familia, quantidade: 1 }, ...prev]
      })

      await adicionarItemInventario(sessaoAtiva.id, { codigo: internalCode, nome: produto.nome, grupo: produto.grupo, familia: produto.familia })
      if (inputRef.current) inputRef.current.value = ''
      haptico()
      mostrarFeedback(produto.nome)
      fetchConsolidado()
    } catch (e: unknown) {
      const error = e as { response?: { status?: number } }
      if (error.response?.status === 404) {
        // Abre modal para adicionar mesmo sem cadastro
        pausaEscaneio.current = true
        setCamera(false)                      // fecha a câmera na hora
        setNaoCadastradoModal({ codigo: codigoLimpo })
        setNaoCadastradoObs('')
        if (inputRef.current) inputRef.current.value = ''
        return
      }
      let msg = 'Erro ao consultar.'
      if (error.response?.status === 400) msg = 'Código inválido.'
      toast({ type: 'error', message: msg })
    } finally {
      processando.current.delete(codigoLimpo)
    }
  }

  function handleKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
    if (e.key === 'Enter' && !pausaEscaneio.current) handleCodigo((e.target as HTMLInputElement).value)
  }

  function ajustarQuantidade(codigo: string, delta: number) {
    if (!sessaoAtiva) return
    let novaQtd = 0
    setItens(prev => {
      const item = prev.find(i => i.codigo === codigo)
      novaQtd = Math.max(0, (item?.quantidade ?? 0) + delta)
      return prev
        .map(i => i.codigo === codigo ? { ...i, quantidade: novaQtd } : i)
        .filter(i => i.quantidade > 0)
    })
    if (novaQtd > 0 || delta < 0) {
      atualizarItemInventario(sessaoAtiva.id, codigo, novaQtd).catch(() => {})
      fetchConsolidado()
    }
  }

  function definirQuantidade(codigo: string, valor: string) {
    if (!sessaoAtiva) return
    setEditando(prev => { const n = { ...prev }; delete n[codigo]; return n })
    const n = parseInt(valor, 10)
    if (isNaN(n) || n < 0) return
    setItens(prev => prev
      .map(i => i.codigo === codigo ? { ...i, quantidade: n } : i)
      .filter(i => i.quantidade > 0)
    )
    atualizarItemInventario(sessaoAtiva.id, codigo, n).catch(() => {})
    fetchConsolidado()
  }

  async function handleLimpar() {
    if (!sessaoAtiva) return
    try {
      await limparItensInventario(sessaoAtiva.id)
      setItens([])
      setConfirmarLimpar(false)
      fetchConsolidado()
    } catch {
      setErro('Erro ao limpar itens')
    }
  }

  // ─── TXT da sessão individual (padrão Alterdata coletador) ───────────────
  function handleExportarTxt() {
    if (itens.length === 0) return
    const linhas = itens.map(i => `${i.codigo};${i.quantidade}`).join('\n')
    const bom = '\uFEFF'
    const blob = new Blob([bom + linhas], { type: 'text/plain;charset=utf-8;' })
    const url = URL.createObjectURL(blob)
    const link = document.createElement('a')
    link.href = url
    link.download = `inventario_${new Date().toISOString().slice(0, 10)}.txt`
    link.click()
    URL.revokeObjectURL(url)
  }

  // ─── Excel da sessão individual (via backend — inclui aba Delta) ──────────
  async function handleExportarExcel() {
    if (!sessaoAtiva || itens.length === 0) return
    setExcelLoading(true)
    setErro('')
    try {
      await exportarExcelSessao(sessaoAtiva.id)
      toast({ type: 'success', message: 'Excel baixado!' })
    } catch {
      setErro('Erro ao gerar Excel')
    } finally {
      setExcelLoading(false)
    }
  }

  const totalItens = itens.reduce((acc, i) => acc + i.quantidade, 0)
  const totalConsolidado = consolidadoItems.reduce((acc, i) => acc + i.quantidade, 0)

  // ─── Estado A: Seleção de sessão ─────────────────────────────────────────
  if (!sessaoAtiva) {
    return (
      <div className="flex flex-col items-center px-4 py-4 overflow-x-auto">
        <div className="w-full max-w-md flex flex-col gap-5">

          {erro && <p className="text-red-500 text-sm" role="alert">{erro}</p>}

          {loadingSessoes ? (
            <div className="flex flex-col gap-3">
              <Skeleton variant="card" />
              <Skeleton variant="card" />
            </div>
          ) : (
            <>
              {sessoes.length > 0 && (
                <Card variant="bordered" padding="md">
                  <h2 className="text-base font-semibold text-text-primary mb-4">Sessões ativas</h2>
                  <div className="flex flex-col gap-2">
                    {sessoes.map(s => (
                      <button
                        key={s.id}
                        onClick={() => setSessaoAtiva(s)}
                        className="flex items-center justify-between border border-border rounded-xl px-4 py-3 text-left hover:bg-primary-lighter transition"
                      >
                        <div>
                          <p className="font-semibold text-sm text-text-primary">{s.nome}</p>
                          <p className="text-xs text-text-muted mt-0.5">
                            Código: <span className="font-mono font-bold text-primary">{s.codigo_convite}</span>
                            {' · '}{s.total_operadores} operador(es) · {s.total_itens} item(ns)
                          </p>
                        </div>
                        <span className="text-xs text-primary font-semibold">Entrar →</span>
                      </button>
                    ))}
                  </div>
                </Card>
              )}

              {isSupervisor && (
                <Button onClick={() => setNovaSessaoModal(true)} fullWidth>
                  <Plus size={16} /> Nova Sessão
                </Button>
              )}
              <div className="flex gap-2">
                <input
                  ref={conviteRef}
                  placeholder="Código da sessão"
                  className="form-input-base flex-1 rounded-xl uppercase min-w-0"
                  onKeyDown={(e) => e.key === 'Enter' && handleEntrarSessao()}
                />
                <Button onClick={handleEntrarSessao}>
                  Entrar
                </Button>
              </div>

              {isSupervisor && (
                <div className="flex gap-2">
                  <Button variant="outline" onClick={handleConsolidadoTxt} fullWidth>
                    <Download size={14} /> TXT Consolidado
                  </Button>
                  <Button onClick={handleConsolidadoExcel} loading={excelConsolidadoLoading} fullWidth>
                    <FileSpreadsheet size={14} /> Excel + Delta
                  </Button>
                </div>
              )}
            </>
          )}

          {/* Modal Nova Sessão */}
          <Modal
            open={novaSessaoModal}
            onClose={() => { setNovaSessaoModal(false); setNovaSessaoNome('') }}
            title="Nova Sessão"
            actions={
              <>
                <Button variant="ghost" onClick={() => { setNovaSessaoModal(false); setNovaSessaoNome('') }}>
                  Cancelar
                </Button>
                <Button onClick={handleCriarSessao} loading={criandoSessao}>
                  Criar
                </Button>
              </>
            }
          >
            <input
              autoFocus
              value={novaSessaoNome}
              onChange={(e) => setNovaSessaoNome(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleCriarSessao()}
              placeholder="Nome da sessão"
              className="form-input-base"
            />
          </Modal>

        </div>
      </div>
    )
  }

  // ─── Estado B/C: Bipagem / Consolidado ──────────────────────────────────
  return (
    <div className="flex flex-col items-center px-4 py-4 overflow-x-auto">
      {camera && (
        <LeitorCodigo
          onLeitura={(codigo) => { handleCodigo(codigo) }}
          onFechar={() => setCamera(false)}
        />
      )}

      <div className="w-full max-w-md flex flex-col gap-5">

        {/* Info da sessão */}
        <div className="flex items-center justify-between gap-2">
          <div className="flex items-center gap-3 min-w-0">
            <button onClick={handleVoltar} className="text-sm text-text-muted hover:text-primary transition shrink-0">
              ← Voltar
            </button>
            <div className="min-w-0">
              <h2 className="text-sm font-bold text-text-primary truncate">{sessaoAtiva.nome}</h2>
              <p className="text-xs text-text-muted font-mono">Código: {sessaoAtiva.codigo_convite}</p>
            </div>
          </div>
          <div className="flex items-center gap-2 shrink-0">
            {isSupervisor && (
              <button onClick={() => setConfirmarEncerrar(true)} className="text-xs text-red-500 hover:text-red-700 transition flex items-center gap-1">
                <LogOut size={12} /> Encerrar
              </button>
            )}
          </div>
        </div>

        {/* Input de bipagem */}
        <Card variant="bordered" padding="md">
          <h2 className="text-base font-semibold text-text-primary mb-4">Bipar produtos</h2>
          <div className="flex gap-2 w-full">
            <input
              ref={inputRef}
              aria-label="Código do produto"
              className="form-input-base flex-1 min-w-0 w-full"
              placeholder="Digite ou bipe o código"
              onKeyDown={handleKeyDown}
              autoFocus
            />
            <button
              onClick={() => setCamera(true)}
              className="md:hidden bg-bg-hover text-text-primary px-2 py-2 rounded-lg transition shrink-0"
              aria-label="Ler código de barras"
            >
              <Camera size={18} />
            </button>
          </div>
          {scanFeedback && (
            <div className="mt-2 flex items-center gap-2 text-success text-sm font-medium animate-fade-in-up">
              <Check size={16} /> {scanFeedback}
            </div>
          )}
          {erro && <p className="text-red-500 text-sm mt-2" role="alert">{erro}</p>}
        </Card>

        {/* Lista de itens */}
        {itens.length > 0 && (
          <Card variant="bordered" padding="md">
            <div className="flex justify-between items-center mb-4">
              <h2 className="text-base font-semibold text-text-primary">
                Contagem
                <span className="text-text-muted font-normal text-sm ml-2">
                  ({itens.length} produtos · {totalItens} unidades)
                </span>
              </h2>
              <div className="flex gap-2">
                <button onClick={() => setConfirmarLimpar(true)} className="text-sm text-text-muted hover:text-red-500 transition flex items-center gap-1">
                  <Trash2 size={14} /> Limpar
                </button>
                <button onClick={handleExportarTxt} className="text-sm text-text-muted hover:text-primary transition flex items-center gap-1">
                  <Download size={14} /> TXT
                </button>
                {isSupervisor && (
                  <Button size="sm" onClick={handleExportarExcel} loading={excelLoading}>
                    <FileSpreadsheet size={14} /> Excel + Delta
                  </Button>
                )}
              </div>
            </div>

            <div className="flex flex-col gap-2">
              {itens.map(item => (
                <div
                  key={item.codigo}
                  onClick={() => setEditSheetItem(item)}
                  className={`flex justify-between items-center border rounded-lg px-3 sm:px-4 py-2 cursor-pointer transition ${
                    highlightedCode === item.codigo
                      ? 'border-primary/50 bg-primary/5 animate-highlight-pulse'
                      : 'border-border hover:bg-bg-hover'
                  }`}
                >
                  <div className="min-w-0 flex-1 overflow-hidden">
                    <div className="flex items-center gap-1.5 flex-nowrap min-w-0">
                      <span className="text-sm font-semibold text-text-primary shrink-0">{item.codigo}</span>
                      <span className="text-xs text-text-muted truncate min-w-0">
                        {item.nome} {item.grupo && item.familia ? `• ${item.grupo} / ${item.familia}` : ''}
                      </span>
                      {item.nome === 'Não cadastrado' && (
                        <span className="shrink-0 inline-flex text-[10px] font-semibold px-1.5 py-0.5 rounded-full bg-amber-50 text-amber-600 dark:bg-amber-900/30 dark:text-amber-400 uppercase tracking-wider">
                          Sem cadastro
                        </span>
                      )}
                    </div>
                    {item.observacao && (
                      <p className="text-[10px] text-text-muted mt-0.5 truncate italic">
                        Obs: {item.observacao}
                      </p>
                    )}
                  </div>
                  <div className="flex items-center gap-1 shrink-0">
                    <button
                      onClick={(e) => { e.stopPropagation(); ajustarQuantidade(item.codigo, -1) }}
                      className="w-6 sm:w-7 h-6 sm:h-7 rounded-full bg-bg-hover text-text-secondary font-bold transition flex items-center justify-center shrink-0"
                    >
                      <Minus size={14} />
                    </button>
                    <input
                      type="number"
                      min="0"
                      value={editando[item.codigo] ?? item.quantidade}
                      onChange={(e) => setEditando(prev => ({ ...prev, [item.codigo]: e.target.value }))}
                      onBlur={(e) => definirQuantidade(item.codigo, e.target.value)}
                      onKeyDown={(e) => {
                        if (e.key === 'Enter') definirQuantidade(item.codigo, (e.target as HTMLInputElement).value)
                      }}
                      onClick={(e) => e.stopPropagation()}
                      className="w-12 sm:w-20 text-center text-sm font-semibold text-text-primary bg-transparent border border-border-input rounded-lg px-1 py-1"
                    />
                    <button
                      onClick={(e) => { e.stopPropagation(); ajustarQuantidade(item.codigo, 1) }}
                      className="w-6 sm:w-7 h-6 sm:h-7 rounded-full bg-bg-hover text-text-secondary font-bold transition flex items-center justify-center shrink-0"
                    >
                      <Plus size={14} />
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </Card>
        )}

        {itens.length === 0 && (
          <p className="text-sm text-text-muted text-center">Nenhum item bipado ainda</p>
        )}

        {/* Consolidado Geral — supervisor only */}
        {isSupervisor && (
          <Card variant="bordered" padding="md">
            <div className="flex justify-between items-center mb-4">
              <h2 className="text-base font-semibold text-text-primary">
                Consolidado Geral
                <span className="text-text-muted font-normal text-sm ml-2">
                  ({consolidadoItems.length} produtos · {totalConsolidado} unidades)
                </span>
              </h2>
              {consolidadoLoading && (
                <span className="text-xs text-text-muted flex items-center gap-1">
                  <svg className="animate-spin h-3 w-3" viewBox="0 0 24 24" fill="none">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z" />
                  </svg>
                  Atualizando...
                </span>
              )}
            </div>

            {consolidadoItems.length === 0 && !consolidadoLoading && (
              <p className="text-sm text-text-muted text-center py-4">Nenhum item em nenhuma sessão</p>
            )}

            {consolidadoItems.length > 0 && (
              <div className="flex flex-col gap-1.5 max-h-60 overflow-y-auto">
                {consolidadoItems.slice(0, 20).map(item => (
                  <div key={item.codigo} className="flex justify-between items-center px-3 py-2 rounded-lg bg-bg-hover">
                    <div className="min-w-0 flex-1">
                      <span className="text-xs font-mono text-text-muted">{item.codigo}</span>
                      <span className="text-xs text-text-muted ml-2 truncate">{item.nome}</span>
                    </div>
                    <span className="text-sm font-bold text-text-primary w-12 text-right">{item.quantidade}</span>
                  </div>
                ))}
                {consolidadoItems.length > 20 && (
                  <p className="text-xs text-text-muted text-center py-2">
                    +{consolidadoItems.length - 20} produtos
                  </p>
                )}
              </div>
            )}
          </Card>
        )}

        {/* Modal Produto Não Cadastrado */}
        <Modal
          open={!!naoCadastradoModal}
          onClose={() => { pausaEscaneio.current = false; ultimaQualquerLeitura.current = Date.now() - 500; setNaoCadastradoModal(null) }}
          title="Produto não encontrado"
          actions={
            <>
              <Button variant="ghost" onClick={() => { pausaEscaneio.current = false; ultimaQualquerLeitura.current = Date.now() - 500; setNaoCadastradoModal(null) }}>
                Cancelar
              </Button>
              <Button onClick={handleAdicionarNaoCadastrado}>
                Adicionar mesmo assim
              </Button>
            </>
          }
        >
          <div className="flex flex-col gap-3">
            <p className="text-sm text-text-secondary">
              O código <strong>{naoCadastradoModal?.codigo}</strong> não está cadastrado no sistema.
            </p>
            <p className="text-xs text-text-muted">
              Se quiser, adicione uma observação para o supervisor ajustar o cadastro depois.
            </p>
            <input
              autoFocus
              value={naoCadastradoObs}
              onChange={(e) => setNaoCadastradoObs(e.target.value)}
              onKeyDown={(e) => { if (e.key === 'Enter') handleAdicionarNaoCadastrado() }}
              placeholder="Ex: EAN estava no rótulo do produto"
              className="form-input-base"
            />
          </div>
        </Modal>

        {/* Modal Editar Item (bottom-sheet) */}
        <Modal
          open={!!editSheetItem}
          onClose={() => setEditSheetItem(null)}
          title="Editar quantidade"
          actions={
            <Button variant="ghost" onClick={() => setEditSheetItem(null)}>
              Fechar
            </Button>
          }
        >
          {editSheetItem && (
            <div>
              <p className="font-semibold text-text-primary">{editSheetItem.codigo}</p>
              <p className="text-xs text-text-muted mt-0.5">{editSheetItem.nome}</p>
              <div className="flex items-center gap-6 mt-5 justify-center">
                <button
                  onClick={() => ajustarQuantidade(editSheetItem.codigo, -1)}
                  className="w-12 h-12 rounded-full bg-bg-hover text-text-secondary font-bold transition flex items-center justify-center"
                >
                  <Minus size={22} />
                </button>
                <input
                  type="number"
                  min="0"
                  value={editando[editSheetItem.codigo] ?? editSheetItem.quantidade}
                  onChange={(e) => setEditando(prev => ({ ...prev, [editSheetItem.codigo]: e.target.value }))}
                  onBlur={(e) => {
                    definirQuantidade(editSheetItem.codigo, e.target.value)
                    setEditSheetItem(null)
                  }}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter') {
                      definirQuantidade(editSheetItem.codigo, (e.target as HTMLInputElement).value)
                      setEditSheetItem(null)
                    }
                  }}
                  className="w-20 text-center text-xl font-bold text-text-primary bg-transparent border border-border-input rounded-lg"
                  autoFocus
                />
                <button
                  onClick={() => ajustarQuantidade(editSheetItem.codigo, 1)}
                  className="w-12 h-12 rounded-full bg-bg-hover text-text-secondary font-bold transition flex items-center justify-center"
                >
                  <Plus size={22} />
                </button>
              </div>
              {editSheetItem.observacao && (
                <p className="text-xs text-text-muted mt-3 text-center italic">
                  Obs: {editSheetItem.observacao}
                </p>
              )}
            </div>
          )}
        </Modal>

        {/* Modal Confirmar Encerrar */}
        <Modal
          open={confirmarEncerrar}
          onClose={() => setConfirmarEncerrar(false)}
          title={`Encerrar "${sessaoAtiva.nome}"?`}
          variant="danger"
          actions={
            <>
              <Button variant="ghost" onClick={() => setConfirmarEncerrar(false)}>Cancelar</Button>
              <Button variant="danger" onClick={handleEncerrarSessao}>
                <LogOut size={14} /> Encerrar
              </Button>
            </>
          }
        >
          <p>Tem certeza? Os operadores não poderão mais bipar itens nesta sessão.</p>
        </Modal>

        {/* Modal Confirmar Limpar */}
        <Modal
          open={confirmarLimpar}
          onClose={() => setConfirmarLimpar(false)}
          title="Limpar todos os itens?"
          variant="danger"
          actions={
            <>
              <Button variant="ghost" onClick={() => setConfirmarLimpar(false)}>Cancelar</Button>
              <Button variant="danger" onClick={handleLimpar}>
                <Trash2 size={14} /> Limpar
              </Button>
            </>
          }
        >
          <p>Todos os itens desta sessão serão removidos permanentemente.</p>
        </Modal>

      </div>
    </div>
  )
}

import { useState } from 'react'
import { useTabelaProdutos } from '../hooks/useTabelaProdutos'
import { Search } from 'lucide-react'
import PageContainer from '../components/layout/PageContainer'
import PageSection from '../components/layout/PageSection'
import DataTable from '../components/ui/DataTable'
import Input from '../components/ui/Input'
import Badge from '../components/ui/Badge'
import EmptyState from '../components/ui/EmptyState'
import ErrorBanner from '../components/ui/ErrorBanner'
import type { ProdutoTabelaResponse, SortByProduto } from '../types'
import { formatCurrency } from '../utils/formatters'

function margemVariant(margem: number): 'success' | 'warning' | 'danger' {
  if (margem < 10) return 'danger'
  if (margem < 20) return 'warning'
  return 'success'
}

function formatPercent(value: number): string {
  return `${value.toFixed(1).replace('.', ',')}%`
}

function codigoLink(codigo: string) {
  return `/bi/sku?codigo=${codigo}`
}

export default function Produtos() {
  const {
    items, total, loading, erro,
    search, setSearch,
    grupo, setGrupo,
    familia, setFamilia,
    sortBy, setSortBy,
    sortOrder, setSortOrder,
    page, setPage,
    pageSize, setPageSize,
    filtrosDisponiveis,
    fetchData,
  } = useTabelaProdutos()

  const [searchInput, setSearchInput] = useState(search)

  function handleSort(col: string) {
    if (sortBy === col) {
      setSortOrder(prev => prev === 'asc' ? 'desc' : 'asc')
    } else {
      setSortBy(col as SortByProduto)
      setSortOrder('asc')
    }
  }

  const columns = [
    {
      key: 'codigo_chamada',
      label: 'Código',
      sortable: true,
      width: '100px',
      render: (item: ProdutoTabelaResponse) => (
        <a
          href={codigoLink(item.codigo_chamada)}
          target="_blank"
          rel="noopener noreferrer"
          className="text-primary hover:underline font-medium"
        >
          {item.codigo_chamada}
        </a>
      ),
    },
    {
      key: 'nome',
      label: 'Produto',
      sortable: true,
      render: (item: ProdutoTabelaResponse) => (
        <a
          href={codigoLink(item.codigo_chamada)}
          target="_blank"
          rel="noopener noreferrer"
          className="text-primary hover:underline"
        >
          <span className="truncate block max-w-[200px]" title={item.nome}>{item.nome}</span>
        </a>
      ),
    },
    {
      key: 'grupo',
      label: 'Grupo',
      sortable: true,
      hide: 'md' as const,
    },
    {
      key: 'familia',
      label: 'Família',
      sortable: true,
      hide: 'md' as const,
    },
    {
      key: 'preco_custo',
      label: 'Custo',
      sortable: true,
      align: 'right' as const,
      render: (item: ProdutoTabelaResponse) => (
        <span className="font-mono">{formatCurrency(item.preco_custo)}</span>
      ),
    },
    {
      key: 'preco_venda',
      label: 'Venda',
      sortable: true,
      align: 'right' as const,
      render: (item: ProdutoTabelaResponse) => (
        <span className="font-mono font-semibold">{formatCurrency(item.preco_venda)}</span>
      ),
    },
    {
      key: 'markup',
      label: 'Markup',
      align: 'right' as const,
      render: (item: ProdutoTabelaResponse) => (
        <span className="text-text-secondary">{formatPercent(item.markup)}</span>
      ),
    },
    {
      key: 'margem',
      label: 'Margem',
      align: 'right' as const,
      render: (item: ProdutoTabelaResponse) => (
        <Badge variant={margemVariant(item.margem)}>
          {formatPercent(item.margem)}
        </Badge>
      ),
    },
    {
      key: 'estoque',
      label: 'Estoque',
      sortable: true,
      align: 'right' as const,
      hide: 'md' as const,
    },
  ]

  return (
    <PageContainer maxWidth="xl">
      <PageSection
        title="Tabela de Preços"
        subtitle="Consulte preços, margens e estoque dos produtos"
      >
        {erro && (
          <ErrorBanner message={erro} onDismiss={fetchData} />
        )}

        {/* Filters */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
          <Input
            icon={<Search size={14} />}
            placeholder="Buscar..."
            value={searchInput}
            onChange={(e) => { setSearchInput(e.target.value); setSearch(e.target.value) }}
          />
          <select
            value={grupo}
            onChange={(e) => setGrupo(e.target.value)}
            className="form-input-base"
          >
            <option value="">Todos os grupos</option>
            {filtrosDisponiveis.grupos.map(g => (
              <option key={g} value={g}>{g}</option>
            ))}
          </select>
          <select
            value={familia}
            onChange={(e) => setFamilia(e.target.value)}
            className="form-input-base"
          >
            <option value="">Todas as famílias</option>
            {filtrosDisponiveis.familias.map(f => (
              <option key={f} value={f}>{f}</option>
            ))}
          </select>
        </div>

        <DataTable
          data={items}
          columns={columns}
          rowKey={(item) => item.codigo_chamada}
          loading={loading}
          sortBy={sortBy}
          sortOrder={sortOrder}
          onSort={handleSort}
          page={page}
          pageSize={pageSize}
          total={total}
          onPageChange={setPage}
          onPageSizeChange={setPageSize}
          empty={<EmptyState title="Nenhum produto encontrado" description="Tente ajustar os filtros da busca." />}
        />
      </PageSection>
    </PageContainer>
  )
}

import { useState, useEffect } from 'react'
import { Trash2, UserPlus, Edit2 } from 'lucide-react'
import {
  listarUsuarios,
  criarUsuario,
  atualizarUsuario,
  excluirUsuario,
  type Usuario,
} from '../api/usuarios'
import { useAuth } from '../hooks/useAuth'
import PageContainer from '../components/layout/PageContainer'
import PageSection from '../components/layout/PageSection'
import Card from '../components/ui/Card'
import UserAvatar from '../components/ui/UserAvatar'
import Input from '../components/ui/Input'
import Button from '../components/ui/Button'
import Modal from '../components/ui/Modal'
import Badge from '../components/ui/Badge'
import EmptyState from '../components/ui/EmptyState'
import type { Role } from '../types'

const ROLES: Role[] = ['operador', 'supervisor', 'admin']

const roleBadgeVariant: Record<Role, 'default' | 'info' | 'warning' | 'success'> = {
  operador: 'default',
  supervisor: 'info',
  admin: 'warning',
}

const roleLabels: Record<Role, string> = {
  operador: 'Operador',
  supervisor: 'Supervisor',
  admin: 'Admin',
}

const ROLES_CONFIG: { value: Role; label: string; desc: string }[] = [
  { value: 'operador', label: 'Operador', desc: 'Acesso a busca e inventário' },
  { value: 'supervisor', label: 'Supervisor', desc: 'Acesso a relatórios e etiquetas' },
  { value: 'admin', label: 'Admin', desc: 'Acesso total ao sistema' },
]

interface ModalEdicao {
  usuario: Usuario
  password: string
  role: Role
  loading: boolean
  erro: string
}

export default function Usuarios() {
  const { getUsername } = useAuth()

  const [usuarios, setUsuarios] = useState<Usuario[]>([])
  const [carregando, setCarregando] = useState(true)
  const [erroGeral, setErroGeral] = useState('')

  const [modal, setModal] = useState<ModalEdicao | null>(null)

  // Novo usuário form
  const [novoUsername, setNovoUsername] = useState('')
  const [novoNome, setNovoNome] = useState('')
  const [novoPassword, setNovoPassword] = useState('')
  const [novoRole, setNovoRole] = useState<Role>('operador')
  const [criando, setCriando] = useState(false)
  const [erroCriacao, setErroCriacao] = useState('')

  const [excluirUsuarioObj, setExcluirUsuarioObj] = useState<Usuario | null>(null)

  const meuUsername = getUsername()

  async function carregar() {
    try {
      const data = await listarUsuarios()
      setUsuarios(data)
      setCarregando(false)
    } catch {
      setErroGeral('Erro ao carregar usuários.')
      setCarregando(false)
    }
  }

  // eslint-disable-next-line react-hooks/set-state-in-effect -- fetch-on-mount legítimo
  useEffect(() => { carregar() }, [])

  async function handleCriar() {
    setErroCriacao('')
    if (!novoUsername.trim() || !novoNome.trim() || !novoPassword.trim()) {
      setErroCriacao('Preencha todos os campos.')
      return
    }
    setCriando(true)
    try {
      await criarUsuario({
        username: novoUsername.trim(),
        nome_exibicao: novoNome.trim(),
        password: novoPassword,
        role: novoRole,
      })
      setNovoUsername('')
      setNovoNome('')
      setNovoPassword('')
      setNovoRole('operador')
      await carregar()
    } catch {
      setErroCriacao('Erro ao criar usuário.')
    } finally {
      setCriando(false)
    }
  }

  async function handleAtualizar() {
    if (!modal) return
    setModal(m => m ? { ...m, loading: true, erro: '' } : null)
    try {
      await atualizarUsuario(modal.usuario.id, {
        role: modal.role,
        ...(modal.password ? { password: modal.password } : {}),
      })
      setModal(null)
      await carregar()
    } catch {
      setModal(m => m ? { ...m, loading: false, erro: 'Erro ao atualizar.' } : null)
    }
  }

  async function handleConfirmarExcluir() {
    if (!excluirUsuarioObj) return
    try {
      await excluirUsuario(excluirUsuarioObj.id)
      setExcluirUsuarioObj(null)
      setCarregando(true)
      await carregar()
    } catch {
      setErroGeral('Erro ao excluir usuário.')
      setExcluirUsuarioObj(null)
    }
  }

  return (
    <PageContainer maxWidth="md">
      {/* Modal de edição */}
      {modal && (
        <Modal
          open={!!modal}
          onClose={() => setModal(null)}
          title={`Editar: ${modal.usuario.nome_exibicao}`}
          actions={
            <>
              <Button variant="ghost" onClick={() => setModal(null)}>Cancelar</Button>
              <Button onClick={handleAtualizar} loading={modal.loading}>Salvar</Button>
            </>
          }
        >
          <div className="flex flex-col gap-4">
            <div className="flex items-center gap-3 mb-2">
              <UserAvatar name={modal.usuario.nome_exibicao} size="sm" />
              <div>
                <p className="text-sm font-semibold text-text-primary">{modal.usuario.nome_exibicao}</p>
                <p className="text-xs text-text-muted font-mono">{modal.usuario.username}</p>
              </div>
            </div>
            <Input
              label="Nova senha (opcional)"
              type="password"
              placeholder="Deixe em branco para não alterar"
              value={modal.password}
              onChange={(e) => setModal(m => m ? { ...m, password: e.target.value } : null)}
            />
            <div className="flex flex-col gap-1.5">
              <label className="form-label">Permissão</label>
              <div className="grid grid-cols-1 gap-1.5">
                {ROLES_CONFIG.map(r => (
                  <button
                    key={r.value}
                    onClick={() => setModal(m => m ? { ...m, role: r.value } : null)}
                    className={`flex items-center gap-3 px-3 py-2.5 rounded-lg border text-sm text-left transition ${
                      modal.role === r.value
                        ? 'border-primary bg-primary-light text-primary'
                        : 'border-border text-text-secondary hover:border-border-input hover:bg-bg-hover'
                    }`}
                  >
                    <span className={`w-4 h-4 rounded-full border-2 flex items-center justify-center shrink-0 ${
                      modal.role === r.value ? 'border-primary' : 'border-text-muted'
                    }`}>
                      {modal.role === r.value && (
                        <span className="w-2 h-2 rounded-full bg-primary" />
                      )}
                    </span>
                    <div>
                      <p className="font-medium">{r.label}</p>
                      <p className="text-xs text-text-muted">{r.desc}</p>
                    </div>
                  </button>
                ))}
              </div>
            </div>
            {modal.erro && <p className="text-danger text-sm">{modal.erro}</p>}
          </div>
        </Modal>
      )}

      {/* Modal confirmar exclusão */}
      <Modal
        open={!!excluirUsuarioObj}
        onClose={() => setExcluirUsuarioObj(null)}
        title={`Excluir "${excluirUsuarioObj?.nome_exibicao}"?`}
        variant="danger"
        actions={
          <>
            <Button variant="ghost" onClick={() => setExcluirUsuarioObj(null)}>Cancelar</Button>
            <Button variant="danger" onClick={handleConfirmarExcluir}>
              <Trash2 size={14} /> Excluir
            </Button>
          </>
        }
      >
        <p className="text-sm text-text-secondary">
          Esta ação não pode ser desfeita. O usuário perderá acesso ao sistema.
        </p>
      </Modal>

      {/* Novo usuário */}
      <PageSection
        title="Novo usuário"
        subtitle="Adicione um novo membro à equipe"
      >
        <Card variant="bordered" padding="md">
          <div className="flex flex-col gap-4">
            {erroGeral && (
              <p className="text-sm text-danger">{erroGeral}</p>
            )}

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <Input
                placeholder="Username"
                value={novoUsername}
                onChange={(e) => setNovoUsername(e.target.value)}
              />
              <Input
                placeholder="Nome de exibição"
                value={novoNome}
                onChange={(e) => setNovoNome(e.target.value)}
              />
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
              <Input
                type="password"
                placeholder="Senha"
                value={novoPassword}
                onChange={(e) => setNovoPassword(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleCriar()}
              />
              <select
                value={novoRole}
                onChange={(e) => setNovoRole(e.target.value as Role)}
                className="form-input-base"
              >
                {ROLES.map(r => <option key={r} value={r}>{roleLabels[r]}</option>)}
              </select>
              <Button
                onClick={handleCriar}
                loading={criando}
                fullWidth
              >
                <UserPlus size={14} /> Criar
              </Button>
            </div>

            {erroCriacao && (
              <p className="text-sm text-danger">{erroCriacao}</p>
            )}
          </div>
        </Card>
      </PageSection>

      {/* Lista de usuários */}
      <PageSection
        title="Equipe"
        subtitle={`${carregando ? '...' : usuarios.length} membro(s)`}
      >
        <Card variant="bordered" padding="none">
          {carregando ? (
            <div className="flex flex-col gap-2 p-5">
              {Array.from({ length: 4 }).map((_, i) => (
                <div key={i} className="h-12 bg-bg-hover rounded-lg animate-pulse" />
              ))}
            </div>
          ) : usuarios.length === 0 ? (
            <EmptyState title="Nenhum usuário" description="Crie o primeiro usuário da equipe." />
          ) : (
            <div className="divide-y divide-border-light">
              {usuarios.map(usuario => (
                <div
                  key={usuario.id}
                  className="flex items-center justify-between px-5 py-3 hover:bg-bg-hover transition group"
                >
                  <div className="flex items-center gap-3 min-w-0">
                    <UserAvatar name={usuario.nome_exibicao} size="sm" />
                    <div className="min-w-0">
                      <p className="text-sm font-semibold text-text-primary truncate">
                        {usuario.nome_exibicao}
                      </p>
                      <p className="text-xs text-text-muted font-mono">{usuario.username}</p>
                    </div>
                    <Badge variant={roleBadgeVariant[usuario.role]}>
                      {roleLabels[usuario.role]}
                    </Badge>
                  </div>

                  <div className="flex gap-1 shrink-0 opacity-0 group-hover:opacity-100 transition">
                    <button
                      onClick={() => setModal({
                        usuario,
                        password: '',
                        role: usuario.role,
                        loading: false,
                        erro: '',
                      })}
                      className="p-1.5 rounded-lg text-text-muted hover:text-primary hover:bg-bg-hover transition"
                      aria-label={`Editar ${usuario.nome_exibicao}`}
                    >
                      <Edit2 size={14} />
                    </button>
                    <button
                      onClick={() => setExcluirUsuarioObj(usuario)}
                      disabled={usuario.username === meuUsername}
                      className="p-1.5 rounded-lg text-text-muted hover:text-danger hover:bg-danger-light transition disabled:opacity-30 disabled:cursor-not-allowed"
                      aria-label={`Excluir ${usuario.nome_exibicao}`}
                    >
                      <Trash2 size={14} />
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </Card>
      </PageSection>
    </PageContainer>
  )
}

/* eslint-disable react-refresh/only-export-components -- Hook + Context + Provider must coexist in one file */
import { createContext, useContext, useRef, useCallback, type ReactNode } from 'react'
import type { PeriodoBi } from '../types'

const MAX_ENTRIES = 50
const MAX_AGE_MS = 10 * 60 * 1000  // 10 minutes

interface CacheEntry {
  data: unknown
  periodoKey: string
  timestamp: number
}

interface BiCacheContextType {
  get: <T>(key: string, periodo: PeriodoBi) => T | null
  set: (key: string, periodo: PeriodoBi, data: unknown) => void
  invalidate: (key: string) => void
  clear: () => void
  getTimestamp: (key: string, periodo: PeriodoBi) => number | null
}

function periodoKey(p: PeriodoBi): string {
  return `${p.data_inicio}_${p.data_fim}`
}

const BiCacheContext = createContext<BiCacheContextType | null>(null)

export function BiCacheProvider({ children }: { children: ReactNode }) {
  const cacheRef = useRef<Map<string, CacheEntry>>(new Map())
  const insertionOrderRef = useRef<string[]>([])

  // Helper: resolve entry + limpa stale (m7 — extraído para evitar duplicação)
  const _resolveEntry = useCallback((key: string, periodo: PeriodoBi): CacheEntry | undefined => {
    const entry = cacheRef.current.get(key)
    if (!entry) return undefined
    if (entry.periodoKey !== periodoKey(periodo)) {
      cacheRef.current.delete(key)
      const idx = insertionOrderRef.current.indexOf(key)
      if (idx !== -1) insertionOrderRef.current.splice(idx, 1)
      return undefined
    }
    if (Date.now() - entry.timestamp > MAX_AGE_MS) {
      cacheRef.current.delete(key)
      const idx = insertionOrderRef.current.indexOf(key)
      if (idx !== -1) insertionOrderRef.current.splice(idx, 1)
      return undefined
    }
    return entry
  }, [])

  const get = useCallback(<T,>(key: string, periodo: PeriodoBi): T | null => {
    const entry = _resolveEntry(key, periodo)
    return entry ? entry.data as T : null
  }, [_resolveEntry])

  const set = useCallback((key: string, periodo: PeriodoBi, data: unknown) => {
    // Track insertion order (only if it's a new key)
    if (!cacheRef.current.has(key)) {
      insertionOrderRef.current.push(key)
    }
    cacheRef.current.set(key, { data, periodoKey: periodoKey(periodo), timestamp: Date.now() })
    // Evict oldest entries FIFO when over limit
    while (insertionOrderRef.current.length > MAX_ENTRIES) {
      const oldestKey = insertionOrderRef.current.shift()
      if (oldestKey) cacheRef.current.delete(oldestKey)
    }
  }, [])

  const invalidate = useCallback((key: string) => {
    cacheRef.current.delete(key)
    const idx = insertionOrderRef.current.indexOf(key)
    if (idx !== -1) insertionOrderRef.current.splice(idx, 1)
  }, [])

  const clear = useCallback(() => {
    cacheRef.current.clear()
    insertionOrderRef.current = []
  }, [])

  const getTimestamp = useCallback((key: string, periodo: PeriodoBi): number | null => {
    const entry = _resolveEntry(key, periodo)
    return entry ? entry.timestamp : null
  }, [_resolveEntry])

  return (
    <BiCacheContext.Provider value={{ get, set, invalidate, clear, getTimestamp }}>
      {children}
    </BiCacheContext.Provider>
  )
}

export function useBiCache(): BiCacheContextType {
  const ctx = useContext(BiCacheContext)
  if (!ctx) throw new Error('useBiCache must be used within BiCacheProvider')
  return ctx
}

import { getConfiguracoes } from '../api/admin'

interface ConfigCache {
  marketName: string
  marketLogoUrl: string
  meta_faturamento_mensal?: string
}

const CACHE_TTL_MS = 30_000

let _cache: ConfigCache | null = null
let _cacheTimestamp = 0
let pendingPromise: Promise<ConfigCache> | null = null

export async function getConfigsCache(): Promise<ConfigCache> {
  const now = Date.now()
  if (_cache && now - _cacheTimestamp < CACHE_TTL_MS) return _cache

  const ls = localStorage.getItem('vitrine_config')
  if (ls) {
    try {
      _cache = JSON.parse(ls) as ConfigCache
      _cacheTimestamp = now
      return _cache
    } catch {
      localStorage.removeItem('vitrine_config')
    }
  }

  // Se já há uma requisição em andamento, aguarda ela em vez de disparar outra
  if (pendingPromise) return pendingPromise

  pendingPromise = getConfiguracoes()
    .then((data) => {
      const c = data.configuracoes
      _cache = {
        marketName: c.market_name ?? '',
        marketLogoUrl: c.logo_url ?? '',
        meta_faturamento_mensal: c.meta_faturamento_mensal ?? undefined,
      }
      _cacheTimestamp = Date.now()
      localStorage.setItem('vitrine_config', JSON.stringify(_cache))
      return _cache
    })
    .catch((err) => {
      // Fallback para localStorage em caso de erro na API
      const cached = localStorage.getItem('vitrine_config')
      if (cached) {
        try {
          _cache = JSON.parse(cached) as ConfigCache
          _cacheTimestamp = Date.now()
          return _cache
        } catch {
          /* ignore - fall through to re-throw */
        }
      }
      throw err
    })
    .finally(() => {
      pendingPromise = null
    })

  return pendingPromise
}

export function invalidateConfigCache(): void {
  _cache = null
  _cacheTimestamp = 0
  localStorage.removeItem('vitrine_config')
}

/** Force reload config from server, bypassing cache and localStorage. */
export async function refreshConfig(): Promise<ConfigCache> {
  _cache = null
  _cacheTimestamp = 0
  localStorage.removeItem('vitrine_config')
  return getConfigsCache()
}

