import type { Role } from '../types'

/**
 * Verifica se o role do usuário corresponde a um dos roles permitidos.
 * Centraliza as comparações de string de role (m1) para evitar que
 * mudanças futuras no enum quebrem comparações espalhadas pelo código.
 */
export function hasRole(userRole: string | null | undefined, allowed: Role[]): boolean {
  if (!userRole) return false
  return allowed.includes(userRole as Role)
}

/**
 * Cria prefixos de badge de role estilizados para UI.
 */
export function getRoleBadge(role: string | null | undefined): { label: string; className: string } {
  switch (role) {
    case 'admin':
      return {
        label: 'Admin',
        className: 'bg-purple-50 text-purple-600 dark:bg-purple-900/30 dark:text-purple-400',
      }
    case 'supervisor':
      return {
        label: 'Sup.',
        className: 'bg-blue-50 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400',
      }
    default:
      return {
        label: 'Op.',
        className: 'bg-gray-100 text-gray-600 dark:bg-gray-800 dark:text-gray-400',
      }
  }
}

export interface CsvRow {
  codigo: string
  tipo: string
  quantidade: number
}

export function gerarCSV(rows: CsvRow[]): string {
  return rows.map(r => `${r.codigo};${r.tipo};${r.quantidade}`).join('\n')
}

export function baixarCSV(conteudo: string, prefixo: string): void {
  const bom = "\uFEFF"
  const blob = new Blob([bom + conteudo], { type: 'text/csv;charset=utf-8;' })
  const url = URL.createObjectURL(blob)
  const link = document.createElement('a')
  link.href = url
  link.download = `${prefixo}_${new Date().toISOString().slice(0, 10)}.csv`
  link.click()
  URL.revokeObjectURL(url)
}

export function baixarCSVdeArray(dados: object[], prefixo: string): boolean {
  if (dados.length === 0) {
    console.warn('baixarCSVdeArray: dados vazios — nada exportado')
    return false
  }
  const cabecalhos = Object.keys(dados[0])
  const linhas = dados.map((linha) =>
    cabecalhos.map((h) => {
      const v = (linha as Record<string, unknown>)[h]
      return v == null ? '' : String(v)
    }).join(';')
  )
  const csv = [cabecalhos.join(';'), ...linhas].join('\n')
  baixarCSV(csv, prefixo)
  return true
}

import { format, parseISO } from 'date-fns'
import { ptBR } from 'date-fns/locale'

export function formatCurrency(value: number): string {
  return value.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })
}

/**
 * Format number with pt-BR locale, no decimals (e.g. "1.234")
 */
export function formatNumber(value: number): string {
  return value.toLocaleString('pt-BR', { maximumFractionDigits: 0 })
}

/**
 * Format ISO date string to "dd MMM yyyy" (e.g. "22 abr 2026")
 */
export function formatDate(iso: string | null): string {
  if (!iso) return '—'
  try {
    return format(parseISO(iso), "dd MMM yyyy", { locale: ptBR })
  } catch {
    return iso
  }
}

/**
 * Format ISO date string to "dd MMMM yyyy - EEEE" (e.g. "22 abril 2026 - Quarta-feira")
 */
export function formatDateWithWeekday(iso: string | null): string {
  if (!iso) return '—'
  try {
    return format(parseISO(iso), "dd MMMM yyyy - EEEE", { locale: ptBR })
  } catch {
    return iso
  }
}

/**
 * Validações client-side que espelham as validações do backend.
 * Previne chamadas de API que seriam rejeitadas com 400/422.
 */

const MAX_RANGE_DIAS_NORMAL = 366
const MAX_RANGE_DIAS_COMPARATIVO = 731
const TOP_MIN = 1
const TOP_MAX = 100

export function validarCodigo(codigo: string): string | null {
  if (!codigo || codigo.trim().length === 0) {
    return 'Código do produto é obrigatório'
  }
  // Backend Codigo value object aceita qualquer string não vazia após strip
  return null
}

export function validarTop(top: number): string | null {
  if (!Number.isInteger(top) || top < TOP_MIN || top > TOP_MAX) {
    return `Top deve ser um número inteiro entre ${TOP_MIN} e ${TOP_MAX}`
  }
  return null
}

export function validarPeriodoBi(
  dataInicio: string,
  dataFim: string,
  comparar: boolean = false,
): string | null {
  const inicio = new Date(dataInicio)
  const fim = new Date(dataFim)

  if (isNaN(inicio.getTime()) || isNaN(fim.getTime())) {
    return 'Datas inválidas. Use o formato YYYY-MM-DD'
  }

  if (fim < inicio) {
    return 'data_fim não pode ser anterior a data_inicio'
  }

  const diffDays = Math.round((fim.getTime() - inicio.getTime()) / (1000 * 60 * 60 * 24))
  const maxDias = comparar ? MAX_RANGE_DIAS_COMPARATIVO : MAX_RANGE_DIAS_NORMAL

  if (diffDays > maxDias) {
    return `Intervalo máximo permitido é de ${maxDias} dias`
  }

  return null
}

export function validarSenha(senha: string): string | null {
  if (!senha || senha.trim().length === 0) {
    return 'Senha não pode ser vazia'
  }
  return null
}

